//! UI declarations: a plugin's sidebar, screens, overlays, home widgets and
//! commands, built from the platform's catalog of primitives and bound to the plugin's own endpoints and topics. It
//! is data in the descriptor: every client renders it with its own components, and every read and action is the
//! member's own call. Nothing here styles anything: tones, emphasis and density are meanings.
//!
//! Field handles are generated by `#[derive(Message)]` (`Order::status: Field<Order, OrderStatus>`), so a column,
//! an argument or a condition over the wrong message or type does not compile.
//!
//! ```ignore
//! let orders = s.query("orders", Query::call(list_orders).rows(ListOrdersResponse::orders).paged().follow(ORDERS));
//! let cancel = s.row_action("cancel", &orders, |a, r| a
//!     .confirm(Confirm::danger("Cancel this order?"))
//!     .call(cancel_order, |c| c.arg(CancelOrderRequest::id, r.get(Order::id)))
//!     .toast("Order cancelled"));
//! table(&orders).col(Order::number, "Order").money(Order::total, "Total", Order::currency)
//!     .row_button(|r| button("Cancel", &cancel).danger().visible(r.get(Order::status).eq(OrderStatus::Placed)))
//! ```

use std::collections::BTreeMap;
use std::future::Future;
use std::marker::PhantomData;
use std::sync::Mutex;

pub use celobus_descriptor::ui as doc;
use celobus_descriptor::ui::{
    Arg, ChartKind, Control, Direction, Emphasis, Format, Kind, Node, OverlayKind, Step, Text,
    TextStyle, Value,
};
pub use celobus_descriptor::ui::{Gap, NoticeTone, Size, Tone};
use serde_json::Value as Json;
/// JSON for the options of a chart: `viz::line::line().options(json!({"fmt": "money"}))`.
pub use serde_json::json;

use crate::ctx::Ctx;
use crate::error::Result;
use crate::message::{FieldValue, Message, Registry};

mod app;
pub use app::*;

// ---------------------------------------------------------------------------------------------- fields and values

/// A typed handle of a message field: `Order::status` is `Field<Order, OrderStatus>`.
pub struct Field<M, T> {
    name: &'static str,
    _p: PhantomData<fn() -> (M, T)>,
}

impl<M, T> Field<M, T> {
    pub const fn new(name: &'static str) -> Self {
        Self {
            name,
            _p: PhantomData,
        }
    }

    pub fn name(&self) -> &'static str {
        self.name
    }
}

impl<M, T> Clone for Field<M, T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<M, T> Copy for Field<M, T> {}

/// The field types a `download` step takes: one file, maybe absent (a list of files is not one).
pub trait OneFile {}
impl OneFile for crate::File {}
impl OneFile for Option<crate::File> {}

/// A value of type `T` from somewhere: a literal, a param, state, a query field, a row field, a form field, the
/// caller, a call result.
pub struct Val<T> {
    v: Value,
    _t: PhantomData<fn() -> T>,
}

impl<T> Clone for Val<T> {
    fn clone(&self) -> Self {
        Self::raw(self.v.clone())
    }
}

impl<T> Val<T> {
    fn raw(v: Value) -> Self {
        Self { v, _t: PhantomData }
    }

    /// The document value.
    pub fn value(&self) -> Value {
        self.v.clone()
    }

    pub fn eq(&self, other: impl IntoVal<T>) -> Cond {
        Cond(doc::Cond::Eq(self.value(), other.into_value()))
    }

    pub fn ne(&self, other: impl IntoVal<T>) -> Cond {
        Cond(doc::Cond::Ne(self.value(), other.into_value()))
    }

    pub fn gt(&self, other: impl IntoVal<T>) -> Cond {
        Cond(doc::Cond::Gt(self.value(), other.into_value()))
    }

    pub fn lt(&self, other: impl IntoVal<T>) -> Cond {
        Cond(doc::Cond::Lt(self.value(), other.into_value()))
    }

    pub fn empty(&self) -> Cond {
        Cond(doc::Cond::Empty(self.value()))
    }

    pub fn is_in(&self, set: impl IntoIterator<Item = T>) -> Cond
    where
        T: FieldValue,
    {
        Cond(doc::Cond::In {
            value: self.value(),
            set: set.into_iter().map(|x| x.encode()).collect(),
        })
    }
}

/// A literal value.
pub fn lit<T: FieldValue>(x: T) -> Val<T> {
    Val::raw(Value::Lit(x.encode()))
}

/// A field of the last call's result in the running chain.
pub fn result<M, T>(f: Field<M, T>) -> Val<T> {
    Val::raw(Value::Result(f.name.into()))
}

/// The member looking at the screen.
pub fn caller_id() -> Val<String> {
    Val::raw(Value::Caller(doc::CallerField::UserId))
}

pub fn caller_name() -> Val<String> {
    Val::raw(Value::Caller(doc::CallerField::DisplayName))
}

/// In `on_error`: the failing call's code and message.
pub fn error_code() -> Val<String> {
    Val::raw(Value::Error(doc::ErrorField::Code))
}

pub fn error_message() -> Val<String> {
    Val::raw(Value::Error(doc::ErrorField::Message))
}

/// What may fill a slot of type `T`: a `Val<T>`, a `Val` of the inner type of an `Option<T>`, or a literal.
pub trait IntoVal<T> {
    fn into_value(self) -> Value;
}

impl<T> IntoVal<T> for Val<T> {
    fn into_value(self) -> Value {
        self.v
    }
}

impl<T> IntoVal<Option<T>> for Val<T> {
    fn into_value(self) -> Value {
        self.v
    }
}

impl<T> IntoVal<T> for &Val<T> {
    fn into_value(self) -> Value {
        self.v.clone()
    }
}

macro_rules! lit_into {
    ($($t:ty => $s:ty),* $(,)?) => {$(
        impl IntoVal<$s> for $t {
            fn into_value(self) -> Value { Value::Lit(serde_json::json!(self)) }
        }
        impl IntoVal<Option<$s>> for $t {
            fn into_value(self) -> Value { Value::Lit(serde_json::json!(self)) }
        }
    )*};
}
lit_into!(&str => String, String => String, bool => bool, i32 => i32, f64 => f64);

impl IntoVal<i64> for i64 {
    fn into_value(self) -> Value {
        Value::Lit(Json::String(self.to_string()))
    }
}

impl IntoVal<Option<i64>> for i64 {
    fn into_value(self) -> Value {
        Value::Lit(Json::String(self.to_string()))
    }
}

impl<E: crate::message::Enum> IntoVal<E> for E {
    fn into_value(self) -> Value {
        Value::Lit(Json::String(self.as_str().into()))
    }
}

/// An enum value where the slot is optional: `a.arg(OrdersParams::status, OrderStatus::Paid)`.
impl<E: crate::message::Enum> IntoVal<Option<E>> for E {
    fn into_value(self) -> Value {
        Value::Lit(Json::String(self.as_str().into()))
    }
}

/// A literal of a param or a state of type `T`: a value of `T`, a value of the inner type when `T` is an `Option`,
/// or a `&str` for a `String`. It is what a param's default ([`S::param_or`]) and the options of a
/// [`segmented`] take.
pub trait LitFor<T> {
    /// The type without its `Option`.
    type Plain;
    fn lit_json(self) -> Json;
}

impl<T: FieldValue> LitFor<T> for T {
    type Plain = T;
    fn lit_json(self) -> Json {
        self.encode()
    }
}

impl<T: FieldValue> LitFor<Option<T>> for T {
    type Plain = T;
    fn lit_json(self) -> Json {
        self.encode()
    }
}

impl LitFor<String> for &str {
    type Plain = String;
    fn lit_json(self) -> Json {
        Json::String(self.into())
    }
}

impl LitFor<Option<String>> for &str {
    type Plain = String;
    fn lit_json(self) -> Json {
        Json::String(self.into())
    }
}

/// A presentation condition (never access control).
#[derive(Clone, Debug)]
pub struct Cond(pub doc::Cond);

impl Cond {
    pub fn and(self, other: Cond) -> Cond {
        Cond(doc::Cond::And(vec![self.0, other.0]))
    }

    pub fn or(self, other: Cond) -> Cond {
        Cond(doc::Cond::Or(vec![self.0, other.0]))
    }
}

pub fn not(c: Cond) -> Cond {
    Cond(doc::Cond::Not(Box::new(c.0)))
}

// ---------------------------------------------------------------------------------------------- texts

static TEXTS: Mutex<BTreeMap<String, String>> = Mutex::new(BTreeMap::new());

/// A text: a literal (`"Orders"`), a catalog key with its English text (`t("nav.all", "All orders")`), or a value.
#[derive(Clone, Debug)]
pub struct Txt(pub Text);

impl From<&str> for Txt {
    fn from(s: &str) -> Self {
        Txt(Text::Plain(s.into()))
    }
}

impl From<String> for Txt {
    fn from(s: String) -> Self {
        Txt(Text::Plain(s))
    }
}

impl<T> From<Val<T>> for Txt {
    fn from(v: Val<T>) -> Self {
        Txt(Text::Value(v.v))
    }
}

/// A catalog text: its key and its English (fallback) text, collected into the descriptor's `en` catalog.
pub fn t(key: &str, en: &str) -> Txt {
    TEXTS.lock().unwrap().insert(key.into(), en.into());
    Txt(Text::Key {
        key: key.into(),
        args: BTreeMap::new(),
    })
}

fn txt(t: impl Into<Txt>) -> Text {
    t.into().0
}

// ---------------------------------------------------------------------------------------------- endpoints, topics

/// The name of the endpoint a handler serves (its request message minus `Request`).
fn endpoint_name<Req: Message>() -> String {
    Req::NAME
        .strip_suffix("Request")
        .filter(|n| !n.is_empty())
        .unwrap_or(Req::NAME)
        .to_string()
}

/// A topic: `pub const ORDERS: Topic<OrderKey> = Topic::new("orders");`. Endpoints declare that they invalidate
/// it (`.invalidates(ORDERS)`); queries follow it.
pub struct Topic<K> {
    name: &'static str,
    _k: PhantomData<fn() -> K>,
}

impl<K> Clone for Topic<K> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<K> Copy for Topic<K> {}

impl<K: Message> Topic<K> {
    pub const fn new(name: &'static str) -> Self {
        Self {
            name,
            _k: PhantomData,
        }
    }

    pub fn name(&self) -> &'static str {
        self.name
    }

    /// The declaration (roles, scopes, the authorizing endpoint).
    pub fn decl(&self) -> TopicDecl {
        TopicDecl {
            name: self.name,
            key: K::NAME,
            register: |r| K::register(r),
            roles: vec![],
            scopes: vec![],
            authorize: None,
            manual: false,
            description: String::new(),
        }
    }

    pub fn roles(&self, roles: impl IntoIterator<Item = crate::identity::Role>) -> TopicDecl {
        self.decl().roles(roles)
    }

    /// A key value: `ORDER.key(|k| k.set(OrderKey::id, param))`.
    pub fn key(&self, f: impl FnOnce(&mut Args<K>) -> &mut Args<K>) -> FollowKey {
        let mut a = Args::new();
        f(&mut a);
        FollowKey {
            topic: self.name.into(),
            key: a.args,
        }
    }
}

/// An endpoint's declared invalidation: a topic, and the key taken from the response.
#[derive(Clone, Debug)]
pub struct Invalidation {
    pub(crate) topic: &'static str,
    pub(crate) key: Vec<(&'static str, &'static str)>,
}

impl<K: Message> From<Topic<K>> for Invalidation {
    fn from(t: Topic<K>) -> Self {
        Invalidation {
            topic: t.name,
            key: vec![],
        }
    }
}

impl<K: Message> Topic<K> {
    /// The key field `key` taken from the response field `from`.
    pub fn by<M, T>(&self, key: Field<K, T>, from: Field<M, T>) -> Invalidation {
        Invalidation {
            topic: self.name,
            key: vec![(key.name, from.name)],
        }
    }
}

impl Invalidation {
    /// Another key field.
    pub fn and<K, M, T>(mut self, key: Field<K, T>, from: Field<M, T>) -> Self {
        self.key.push((key.name, from.name));
        self
    }

    pub(crate) fn json(&self) -> Json {
        let mut v = serde_json::json!({ "topic": self.topic });
        if !self.key.is_empty() {
            v["key"] = Json::Array(
                self.key
                    .iter()
                    .map(|(f, from)| serde_json::json!({ "field": f, "from": from }))
                    .collect(),
            );
        }
        v
    }
}

/// A topic as the plugin declares it.
#[derive(Clone)]
pub struct TopicDecl {
    pub(crate) name: &'static str,
    pub(crate) key: &'static str,
    pub(crate) register: fn(&mut Registry),
    pub(crate) roles: Vec<String>,
    pub(crate) scopes: Vec<String>,
    pub(crate) authorize: Option<String>,
    pub(crate) manual: bool,
    pub(crate) description: String,
}

impl TopicDecl {
    pub fn roles(mut self, roles: impl IntoIterator<Item = crate::identity::Role>) -> Self {
        self.roles = roles.into_iter().map(|r| r.name().to_string()).collect();
        self
    }

    pub fn scopes(mut self, scopes: impl IntoIterator<Item = crate::identity::Scope>) -> Self {
        self.scopes = scopes.into_iter().map(|s| s.name().to_string()).collect();
        self
    }

    /// The read endpoint that decides whether a member may follow one key (it takes the key's fields).
    pub fn authorize<Req: Message, Resp: Message, F, Fut>(mut self, _handler: F) -> Self
    where
        F: Fn(Ctx, Req) -> Fut,
        Fut: Future<Output = Result<Resp>>,
    {
        self.authorize = Some(endpoint_name::<Req>());
        self
    }

    /// Invalidated by code (`ctx.invalidate`) rather than by endpoint declarations.
    pub fn manual(mut self) -> Self {
        self.manual = true;
        self
    }

    pub fn describe(mut self, d: impl Into<String>) -> Self {
        self.description = d.into();
        self
    }

    pub(crate) fn json(&self) -> Json {
        let mut v = serde_json::json!({ "name": self.name, "key": self.key, "description": self.description });
        if !self.roles.is_empty() {
            v["roles"] = serde_json::json!(self.roles);
        }
        if !self.scopes.is_empty() {
            v["scopes"] = serde_json::json!(self.scopes);
        }
        if let Some(a) = &self.authorize {
            v["authorize"] = serde_json::json!(a);
        }
        if self.manual {
            v["manual"] = serde_json::json!(true);
        }
        v
    }
}

impl<K: Message> From<Topic<K>> for TopicDecl {
    fn from(t: Topic<K>) -> Self {
        t.decl()
    }
}

/// A followed topic with a key value.
#[derive(Clone)]
pub struct FollowKey {
    topic: String,
    key: Vec<Arg>,
}

impl<K: Message> From<Topic<K>> for FollowKey {
    fn from(t: Topic<K>) -> Self {
        FollowKey {
            topic: t.name.into(),
            key: vec![],
        }
    }
}

/// Request (or key, or params) fields set to values: `|c| c.arg(CancelOrderRequest::id, r.get(Order::id))`.
pub struct Args<M> {
    args: Vec<Arg>,
    _m: PhantomData<fn() -> M>,
}

impl<M> Args<M> {
    fn new() -> Self {
        Self {
            args: vec![],
            _m: PhantomData,
        }
    }

    pub fn arg<T>(&mut self, f: Field<M, T>, v: impl IntoVal<T>) -> &mut Self {
        self.args.push(Arg {
            field: f.name.into(),
            value: v.into_value(),
        });
        self
    }

    /// The same as [`Args::arg`], for a key.
    pub fn set<T>(&mut self, f: Field<M, T>, v: impl IntoVal<T>) -> &mut Self {
        self.arg(f, v)
    }
}

// ---------------------------------------------------------------------------------------------- queries

/// A query definition: `Query::call(list_orders).arg(..).rows(ListOrdersResponse::orders).paged().follow(ORDERS)`.
pub struct QueryDef<Req, Resp, Row> {
    q: doc::Query,
    #[allow(clippy::type_complexity)]
    _p: PhantomData<fn() -> (Req, Resp, Row)>,
}

pub struct Query;

impl Query {
    /// A call of one of the plugin's read-only `ui` endpoints, by its handler.
    pub fn call<Req: Message, Resp: Message, F, Fut>(_handler: F) -> QueryDef<Req, Resp, Resp>
    where
        F: Fn(Ctx, Req) -> Fut,
        Fut: Future<Output = Result<Resp>>,
    {
        QueryDef {
            q: doc::Query {
                when: None,
                name: String::new(),
                endpoint: endpoint_name::<Req>(),
                args: vec![],
                rows: None,
                paged: false,
                feed: None,
                follow: vec![],
                poll: None,
                max_age: None,
                older: None,
                debounce_ms: None,
                join: vec![],
            },
            _p: PhantomData,
        }
    }
}

impl<Req, Resp, Row> QueryDef<Req, Resp, Row> {
    pub fn arg<T>(mut self, f: Field<Req, T>, v: impl IntoVal<T>) -> Self {
        self.q.args.push(Arg {
            field: f.name.into(),
            value: v.into_value(),
        });
        self
    }

    /// The repeated field tables, lists and charts iterate.
    pub fn rows<R>(mut self, f: Field<Resp, Vec<R>>) -> QueryDef<Req, Resp, R> {
        self.q.rows = Some(f.name.into());
        QueryDef {
            q: self.q,
            _p: PhantomData,
        }
    }

    /// `page_token`/`page_size` in the request, `next_page_token` in the response.
    pub fn paged(mut self) -> Self {
        self.q.paged = true;
        self
    }

    /// Re-run on the topic's invalidations (any key, or one key: `ORDER.key(|k| k.set(..))`).
    pub fn follow(mut self, t: impl Into<FollowKey>) -> Self {
        let k = t.into();
        self.q.follow.push(doc::Follow {
            topic: k.topic,
            key: k.key,
            min_interval_ms: None,
        });
        self
    }

    /// As `follow`, re-run at most every `min_interval_ms` however often the topic's key changes (a live tail
    /// while an agent writes: `.follow_every(RUNS.key(..), 1000)`).
    pub fn follow_every(mut self, t: impl Into<FollowKey>, min_interval_ms: u32) -> Self {
        self = self.follow(t);
        if let Some(f) = self.q.follow.last_mut() {
            f.min_interval_ms = Some(min_interval_ms);
        }
        self
    }

    /// An append-only feed: `after` takes the last cursor, `cursor` gives it, rows are deduplicated by `key`.
    pub fn feed<A, C, K>(
        mut self,
        after: Field<Req, A>,
        cursor: Field<Resp, C>,
        key: Field<Row, K>,
    ) -> Self {
        self.q.feed = Some(doc::Feed {
            after: after.name.into(),
            cursor: cursor.name.into(),
            key: key.name.into(),
        });
        self
    }

    /// Re-run every `seconds` (at least 15).
    pub fn poll(mut self, seconds: u32) -> Self {
        self.q.poll = Some(seconds);
        self
    }

    /// The oldest the data may get while shown (seconds).
    pub fn max_age(mut self, seconds: u32) -> Self {
        self.q.max_age = Some(seconds);
        self
    }
}

/// A declared query of a screen, an overlay or the document: read its fields, iterate its rows.
pub struct Q<Resp, Row> {
    name: String,
    _p: PhantomData<fn() -> (Resp, Row)>,
}

impl<Resp, Row> Clone for Q<Resp, Row> {
    fn clone(&self) -> Self {
        Self {
            name: self.name.clone(),
            _p: PhantomData,
        }
    }
}

impl<Resp, Row> Q<Resp, Row> {
    /// A field of the response (one record).
    pub fn field<T>(&self, f: Field<Resp, T>) -> Val<T> {
        Val::raw(Value::Data {
            query: self.name.clone(),
            field: f.name.into(),
        })
    }

    /// A nested field by path (`customer.name`).
    pub fn path<T>(&self, path: &str) -> Val<T> {
        Val::raw(Value::Data {
            query: self.name.clone(),
            field: path.into(),
        })
    }

    pub fn name(&self) -> &str {
        &self.name
    }
}

/// The current row of a table, list, chart or row menu.
pub struct Row<R> {
    _r: PhantomData<fn() -> R>,
}

impl<R> Row<R> {
    fn new() -> Self {
        Self { _r: PhantomData }
    }

    pub fn get<T>(&self, f: Field<R, T>) -> Val<T> {
        Val::raw(Value::Row(f.name.into()))
    }
}

impl<R> Clone for Row<R> {
    fn clone(&self) -> Self {
        Self::new()
    }
}

/// The values of the enclosing form.
pub struct FormVals<Req> {
    _r: PhantomData<fn() -> Req>,
}

impl<Req> FormVals<Req> {
    pub fn get<T>(&self, f: Field<Req, T>) -> Val<T> {
        Val::raw(Value::Form(f.name.into()))
    }
}

