/// A screen or overlay param.
pub struct ParamRef<T> {
    name: &'static str,
    _t: PhantomData<fn() -> T>,
}

impl<T> Clone for ParamRef<T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<T> Copy for ParamRef<T> {}

impl<T> ParamRef<T> {
    pub fn val(&self) -> Val<T> {
        Val::raw(Value::Param(self.name.into()))
    }

    fn input(&self, control: Control, label: impl Into<Txt>) -> InputB {
        InputB(doc::Input {
            icon: None,
            width: None,
            stepper: false,
            aside: None,
            add_label: None,
            name: self.name.into(),
            control,
            label: txt(label),
            help: None,
            placeholder: None,
            required: false,
            initial: None,
            options: vec![],
            options_from: None,
            fields: vec![],
            min_items: None,
            max_items: None,
            pick: None,
            max_size: None,
            accept: vec![],
            multiple: false,
        })
    }

    /// A select in a filter bar (the options of an enum, or `.option(..)`).
    pub fn select(&self, label: impl Into<Txt>) -> InputB
    where
        T: SelectOptions,
    {
        let mut i = self.input(Control::Select, label);
        i.0.options = T::options();
        i
    }

    pub fn search(&self, label: impl Into<Txt>) -> InputB {
        self.input(Control::Search, label)
    }

    /// A select in a filter bar with the options listed by `.option(value, label)` (any param type).
    pub fn choice(&self, label: impl Into<Txt>) -> InputB {
        self.input(Control::Select, label)
    }

    /// A filter that takes several of the options listed by `.option(value, label)`. The param is a string: the
    /// chosen values joined with commas, in the options' order (`unpaid,pending`); the endpoint splits it and
    /// matches any of them.
    pub fn choices(&self, label: impl Into<Txt>) -> InputB {
        self.input(Control::MultiSelect, label)
    }

    pub fn date(&self, label: impl Into<Txt>) -> InputB {
        self.input(Control::Date, label)
    }
}

impl<T> ParamRef<Option<T>> {
    /// An optional param passed where a plain value is wanted: absent, the argument is left out (its default).
    pub fn or_empty(&self) -> Val<T> {
        Val::raw(Value::Param(self.name.into()))
    }
}

impl<T> IntoVal<T> for ParamRef<T> {
    fn into_value(self) -> Value {
        Value::Param(self.name.into())
    }
}

/// A param that always has a value (a required one, or one with a default) where the slot is optional: the range
/// of a report carried to a link.
impl<T> IntoVal<Option<T>> for ParamRef<T> {
    fn into_value(self) -> Value {
        Value::Param(self.name.into())
    }
}

/// Options a select gets by itself: an enum's values (and an `Option` of it).
pub trait SelectOptions {
    fn options() -> Vec<doc::Opt>;
}

impl<E: crate::message::Enum> SelectOptions for E {
    fn options() -> Vec<doc::Opt> {
        E::VALUES
            .iter()
            .map(|v| doc::Opt {
                value: Json::String((*v).into()),
                label: Text::Plain(label_of(v)),
            })
            .collect()
    }
}

impl<E: crate::message::Enum> SelectOptions for Option<E> {
    fn options() -> Vec<doc::Opt> {
        E::options()
    }
}

/// `in_progress` → `In progress`.
fn label_of(v: &str) -> String {
    let s = v.replace('_', " ");
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => s,
    }
}

/// A state value of a screen or overlay.
pub struct StateRef<T> {
    name: String,
    _t: PhantomData<fn() -> T>,
}

impl<T> Clone for StateRef<T> {
    fn clone(&self) -> Self {
        Self {
            name: self.name.clone(),
            _t: PhantomData,
        }
    }
}

impl<T> StateRef<T> {
    pub fn val(&self) -> Val<T> {
        Val::raw(Value::State(self.name.clone()))
    }
}

impl<T> IntoVal<T> for &StateRef<T> {
    fn into_value(self) -> Value {
        Value::State(self.name.clone())
    }
}

/// A declared action (a chain of steps).
#[derive(Clone)]
pub struct ActionRef(String);

/// Where screens and overlays keep their pieces.
struct Scope {
    params: Vec<doc::Param>,
    state: Vec<doc::State>,
    queries: Vec<doc::Query>,
    actions: Vec<doc::Action>,
    overlays: Vec<doc::Overlay>,
    header: Vec<Node>,
    title: Option<Text>,
    subtitle: Option<Text>,
    kicker: Option<Text>,
    size: Size,
    counter: usize,
}

impl Scope {
    fn new() -> Self {
        Self {
            params: vec![],
            state: vec![],
            queries: vec![],
            actions: vec![],
            overlays: vec![],
            header: vec![],
            title: None,
            subtitle: None,
            kicker: None,
            size: Size::Medium,
            counter: 0,
        }
    }

    fn params_of<P: Message>(&mut self) {
        let mut reg = Registry::default();
        P::register(&mut reg);
        if let Some(m) = reg.messages.iter().find(|m| m.name == P::NAME) {
            for f in &m.fields {
                self.params.push(doc::Param {
                    name: f.name.to_string(),
                    ty: f.ty.spelled(""),
                    required: !f.ty.optional && !f.ty.repeated,
                    default: None,
                });
            }
        }
    }
}

/// The builder a screen's or overlay's closure gets.
pub struct S<P> {
    scope: Scope,
    _p: PhantomData<fn() -> P>,
}

impl<P: Message> S<P> {
    fn new() -> Self {
        let mut scope = Scope::new();
        scope.params_of::<P>();
        Self {
            scope,
            _p: PhantomData,
        }
    }

    pub fn title(&mut self, t: impl Into<Txt>) -> &mut Self {
        self.scope.title = Some(txt(t));
        self
    }

    pub fn subtitle(&mut self, t: impl Into<Txt>) -> &mut Self {
        self.scope.subtitle = Some(txt(t));
        self
    }

    /// An overlay's size.
    pub fn size(&mut self, size: Size) -> &mut Self {
        self.scope.size = size;
        self
    }

    /// A param of the params message (a filter, a record id).
    pub fn param<T>(&self, f: Field<P, T>) -> ParamRef<T> {
        ParamRef {
            name: f.name,
            _t: PhantomData,
        }
    }

    /// A param with a default: a screen opened without it behaves as if the link had the default (the queries get
    /// it, a `segmented` or a tab bound to it shows it selected), and the link stays without it. The param always
    /// has a value, so the handle is of the plain type even when the field is an `Option`:
    /// `let range = s.param_or(ReportParams::range, "30");` is a `ParamRef<String>`.
    pub fn param_or<T, D: LitFor<T>>(&mut self, f: Field<P, T>, default: D) -> ParamRef<D::Plain> {
        if let Some(p) = self.scope.params.iter_mut().find(|p| p.name == f.name) {
            p.default = Some(default.lit_json());
            p.required = false;
        }
        ParamRef {
            name: f.name,
            _t: PhantomData,
        }
    }

    /// State with its default.
    pub fn state<T: FieldValue>(&mut self, name: &str, default: T) -> StateRef<T> {
        let mut reg = Registry::default();
        let ty = T::field_type(&mut reg).spelled("");
        self.scope.state.push(doc::State {
            name: name.into(),
            ty,
            default: Some(default.encode()),
            reset: vec![],
        });
        StateRef {
            name: name.into(),
            _t: PhantomData,
        }
    }

    pub fn query<Req, Resp, Row>(
        &mut self,
        name: &str,
        def: QueryDef<Req, Resp, Row>,
    ) -> Q<Resp, Row> {
        let mut q = def.q;
        q.name = name.into();
        self.scope.queries.push(q);
        Q {
            name: name.into(),
            _p: PhantomData,
        }
    }

    /// A chain of steps run by a button, a menu item or a row open.
    pub fn action(&mut self, name: &str, f: impl FnOnce(&mut Chain) -> &mut Chain) -> ActionRef {
        let mut c = Chain::new();
        f(&mut c);
        self.push_action(name, c)
    }

    /// A chain that reads the row it is run on (`r.get(Order::id)`).
    pub fn row_action<Resp, R>(
        &mut self,
        name: &str,
        _rows: &Q<Resp, R>,
        f: impl FnOnce(&mut Chain, Row<R>) -> &mut Chain,
    ) -> ActionRef {
        let mut c = Chain::new();
        f(&mut c, Row::new());
        self.push_action(name, c)
    }

    fn push_action(&mut self, name: &str, c: Chain) -> ActionRef {
        self.scope.actions.push(doc::Action {
            name: name.into(),
            steps: c.steps,
            on_error: c.on_error,
        });
        ActionRef(name.into())
    }

    /// Buttons and menus in the header (a screen) or the footer (a dialog).
    pub fn header(&mut self, nodes: impl IntoIterator<Item = N>) -> &mut Self {
        self.scope.header.extend(nodes.into_iter().map(|n| n.0));
        self
    }

    /// An overlay this screen opens (`a.open(EDIT, |p| ..)`).
    pub fn overlay(&mut self, o: Overlay) -> &mut Self {
        self.scope.overlays.push(o.0);
        self
    }

    /// A form filling `handler`'s request; its submit runs the chain `submit` builds (`a.call_form(handler, ..)`).
    pub fn form<Req: Message, Resp: Message, F, Fut>(
        &mut self,
        _handler: F,
        build: impl FnOnce(&mut FormB<Req>),
        submit_label: impl Into<Txt>,
        submit: impl FnOnce(&mut Chain, FormVals<Req>) -> &mut Chain,
    ) -> N
    where
        F: Fn(Ctx, Req) -> Fut + Clone,
        Fut: Future<Output = Result<Resp>>,
    {
        let mut fb = FormB::<Req> {
            sections: vec![doc::FormSection {
                title: None,
                inputs: vec![],
            }],
            cancel: None,
            summary: None,
            note: None,
            alternate: None,
            notes: vec![],
            phone_submit: None,
            _r: PhantomData,
        };
        build(&mut fb);
        let alternate = fb.alternate.take().map(|(label, chain)| {
            self.scope.counter += 1;
            let name = format!("alternate_{}", self.scope.counter);
            let a = self.push_action(&name, chain);
            doc::FormButton { label, action: a.0 }
        });
        self.scope.counter += 1;
        let name = format!("submit_{}", self.scope.counter);
        let mut c = Chain::new();
        submit(&mut c, FormVals { _r: PhantomData });
        let a = self.push_action(&name, c);
        N::of(Kind::Form(doc::Form {
            summary: fb.summary,
            note: fb.note,
            alternate,
            endpoint: endpoint_name::<Req>(),
            sections: fb
                .sections
                .into_iter()
                .filter(|s| !s.inputs.is_empty())
                .collect(),
            submit: a.0,
            submit_label: txt(submit_label),
            phone_submit_label: fb.phone_submit,
            cancel_label: fb.cancel,
            notes: fb.notes,
        }))
    }
}

/// A built screen.
pub struct Screen(pub(crate) doc::Screen);

impl Screen {
    pub fn build<P: Message>(key: ScreenKey<P>, f: impl FnOnce(&mut S<P>) -> N) -> Screen {
        let mut s = S::<P>::new();
        let layout = f(&mut s).0;
        let sc = s.scope;
        Screen(doc::Screen {
            id: key.id.into(),
            title: sc.title.unwrap_or_else(|| Text::Plain(label_of(key.id))),
            subtitle: sc.subtitle,
            params: sc.params,
            state: sc.state,
            queries: sc.queries,
            actions: sc.actions,
            overlays: sc.overlays,
            header: sc.header,
            layout,
        })
    }
}

/// A built overlay.
pub struct Overlay(pub(crate) doc::Overlay);

impl Overlay {
    fn build<P: Message>(
        key: OverlayKey<P>,
        kind: OverlayKind,
        f: impl FnOnce(&mut S<P>) -> N,
    ) -> Overlay {
        let mut s = S::<P>::new();
        let layout = f(&mut s).0;
        let sc = s.scope;
        for p in &sc.params {
            let _ = p;
        }
        Overlay(doc::Overlay {
            kicker: sc.kicker,
            id: key.id.into(),
            kind,
            size: sc.size,
            title: sc.title.unwrap_or_else(|| Text::Plain(label_of(key.id))),
            params: sc.params,
            state: sc.state,
            queries: sc.queries,
            actions: sc.actions,
            buttons: sc.header,
            layout,
        })
    }

    pub fn dialog<P: Message>(key: OverlayKey<P>, f: impl FnOnce(&mut S<P>) -> N) -> Overlay {
        Self::build(key, OverlayKind::Dialog, f)
    }

    pub fn side_panel<P: Message>(key: OverlayKey<P>, f: impl FnOnce(&mut S<P>) -> N) -> Overlay {
        Self::build(key, OverlayKind::SidePanel, f)
    }

    pub fn sheet<P: Message>(key: OverlayKey<P>, f: impl FnOnce(&mut S<P>) -> N) -> Overlay {
        Self::build(key, OverlayKind::Sheet, f)
    }
}

// ---------------------------------------------------------------------------------------------- actions

/// A chain of steps: `a.confirm(..).call(..).toast(..).close()`; `on_error` for the failure branch.
pub struct Chain {
    steps: Vec<Step>,
    on_error: Vec<Step>,
}

/// A confirmation before the next steps.
pub struct Confirm(doc::Confirm);

impl Confirm {
    pub fn new(title: impl Into<Txt>) -> Self {
        Confirm(doc::Confirm {
            cancel_label: None,
            summary: None,
            summary_icon: None,
            title: txt(title),
            text: None,
            confirm_label: None,
            danger: false,
            typed: None,
        })
    }

    pub fn danger(title: impl Into<Txt>) -> Self {
        let mut c = Self::new(title);
        c.0.danger = true;
        c
    }

    pub fn text(mut self, t: impl Into<Txt>) -> Self {
        self.0.text = Some(txt(t));
        self
    }

    pub fn confirm_label(mut self, t: impl Into<Txt>) -> Self {
        self.0.confirm_label = Some(txt(t));
        self
    }

    /// The member types this value to confirm.
    pub fn typed<T>(mut self, v: impl IntoVal<T>) -> Self {
        self.0.typed = Some(v.into_value());
        self
    }
}

impl Chain {
    fn new() -> Self {
        Self {
            steps: vec![],
            on_error: vec![],
        }
    }

    pub fn confirm(&mut self, c: Confirm) -> &mut Self {
        self.steps.push(Step::Confirm(c.0));
        self
    }

    /// Calls a `ui` endpoint as the member.
    pub fn call<Req: Message, Resp: Message, F, Fut>(
        &mut self,
        _handler: F,
        args: impl FnOnce(&mut Args<Req>) -> &mut Args<Req>,
    ) -> &mut Self
    where
        F: Fn(Ctx, Req) -> Fut,
        Fut: Future<Output = Result<Resp>>,
    {
        let mut a = Args::new();
        args(&mut a);
        self.steps.push(Step::Call(doc::Call {
            endpoint: endpoint_name::<Req>(),
            args: a.args,
            form: false,
            pending: None,
        }));
        self
    }

    /// Calls with the form's values (and `args` over them); `pending` shows them as a row of that query until the
    /// re-read returns it.
    pub fn call_form<Req: Message, Resp: Message, F, Fut>(
        &mut self,
        _handler: F,
        args: impl FnOnce(&mut Args<Req>) -> &mut Args<Req>,
    ) -> &mut Self
    where
        F: Fn(Ctx, Req) -> Fut,
        Fut: Future<Output = Result<Resp>>,
    {
        let mut a = Args::new();
        args(&mut a);
        self.steps.push(Step::Call(doc::Call {
            endpoint: endpoint_name::<Req>(),
            args: a.args,
            form: true,
            pending: None,
        }));
        self
    }

    /// The last call shows a pending row in `rows` until a re-read returns it.
    pub fn pending<Resp, R>(&mut self, rows: &Q<Resp, R>) -> &mut Self {
        if let Some(Step::Call(c)) = self.steps.last_mut() {
            c.pending = Some(rows.name.clone());
        }
        self
    }

    pub fn toast(&mut self, t: impl Into<Txt>) -> &mut Self {
        self.steps.push(Step::Toast(doc::Toast {
            description: None,
            action: None,
            text: Some(txt(t)),
            tone: None,
            error: false,
        }));
        self
    }

    pub fn toast_tone(&mut self, t: impl Into<Txt>, tone: Tone) -> &mut Self {
        self.steps.push(Step::Toast(doc::Toast {
            description: None,
            action: None,
            text: Some(txt(t)),
            tone: Some(tone),
            error: false,
        }));
        self
    }

    /// In `on_error`: the failing call's own message.
    pub fn toast_error(&mut self) -> &mut Self {
        self.steps.push(Step::Toast(doc::Toast {
            description: None,
            action: None,
            text: None,
            tone: Some(Tone::Danger),
            error: true,
        }));
        self
    }

    pub fn open<P>(
        &mut self,
        o: OverlayKey<P>,
        args: impl FnOnce(&mut Args<P>) -> &mut Args<P>,
    ) -> &mut Self {
        let mut a = Args::new();
        args(&mut a);
        self.steps.push(Step::Open(doc::Target {
            screen: None,
            overlay: Some(o.id.into()),
            args: a.args,
        }));
        self
    }

    pub fn close(&mut self) -> &mut Self {
        self.steps.push(Step::Close {});
        self
    }

    pub fn navigate<P>(
        &mut self,
        s: ScreenKey<P>,
        args: impl FnOnce(&mut Args<P>) -> &mut Args<P>,
    ) -> &mut Self {
        let mut a = Args::new();
        args(&mut a);
        self.steps.push(Step::Navigate(doc::Target {
            screen: Some(s.id.into()),
            overlay: None,
            args: a.args,
        }));
        self
    }

    pub fn back(&mut self) -> &mut Self {
        self.steps.push(Step::Back {});
        self
    }

    pub fn set<T>(&mut self, state: &StateRef<T>, v: impl IntoVal<T>) -> &mut Self {
        self.steps.push(Step::Set(doc::Set {
            state: Some(state.name.clone()),
            param: None,
            value: v.into_value(),
        }));
        self
    }

    pub fn set_param<T>(&mut self, p: ParamRef<T>, v: impl IntoVal<T>) -> &mut Self {
        self.steps.push(Step::Set(doc::Set {
            state: None,
            param: Some(p.name.into()),
            value: v.into_value(),
        }));
        self
    }

    /// Re-run these queries (none: every query of the screen).
    pub fn refresh(&mut self, queries: &[&str]) -> &mut Self {
        self.steps.push(Step::Refresh {
            queries: queries.iter().map(|q| q.to_string()).collect(),
        });
        self
    }

    pub fn open_url(&mut self, url: impl IntoVal<String>) -> &mut Self {
        self.steps.push(Step::OpenUrl {
            value: url.into_value(),
        });
        self
    }

    /// Downloads the file the last call answered in `f` (a `File` or `Option<File>` field of its answer), then goes
    /// on: `a.call(export_orders, |c| c).download(ExportOrdersReply::file)`. The person's browser saves it; an
    /// answer without the file stops the chain like a failed step (`on_error` runs).
    pub fn download<M, T: OneFile>(&mut self, f: Field<M, T>) -> &mut Self {
        self.steps.push(Step::Download(f.name.into()));
        self
    }

    /// The steps run when a step fails.
    pub fn on_error(&mut self, f: impl FnOnce(&mut Chain) -> &mut Chain) -> &mut Self {
        let mut c = Chain::new();
        f(&mut c);
        self.on_error = c.steps;
        self
    }
}

// ---------------------------------------------------------------------------------------------- nodes

/// A primitive with its common options: `.visible(cond)`, `.enabled(cond)`, `.fallback(node)`.
#[derive(Clone, Debug)]
pub struct N(pub Node);

impl N {
    fn of(k: Kind) -> Self {
        N(Node::from(k))
    }

    pub fn visible(mut self, c: Cond) -> Self {
        self.0.visible = Some(c.0);
        self
    }

    pub fn enabled(mut self, c: Cond) -> Self {
        self.0.enabled = Some(c.0);
        self
    }

    pub fn fallback(mut self, n: N) -> Self {
        self.0.fallback = Some(Box::new(n.0));
        self
    }
}

fn nodes(children: impl IntoIterator<Item = N>) -> Vec<Node> {
    children.into_iter().map(|n| n.0).collect()
}

pub fn stack(children: impl IntoIterator<Item = N>) -> N {
    N::of(Kind::Stack(doc::Stack {
        justify: None,
        direction: Direction::Vertical,
        gap: Gap::Normal,
        children: nodes(children),
    }))
}

/// Children side by side (wrapping on a phone).
pub fn row(children: impl IntoIterator<Item = N>) -> N {
    N::of(Kind::Stack(doc::Stack {
        justify: None,
        direction: Direction::Horizontal,
        gap: Gap::Normal,
        children: nodes(children),
    }))
}

impl N {
    /// The gap of a stack or row.
    pub fn gap(mut self, gap: Gap) -> Self {
        if let Kind::Stack(s) = &mut self.0.kind {
            s.gap = gap;
        }
        self
    }

    /// Relative widths of columns (`[2, 1]`).
    pub fn ratios(mut self, r: impl IntoIterator<Item = u32>) -> Self {
        if let Kind::Columns(c) = &mut self.0.kind {
            c.ratios = r.into_iter().collect();
        }
        self
    }

    pub fn description(mut self, t: impl Into<Txt>) -> Self {
        if let Kind::Section(s) = &mut self.0.kind {
            s.description = Some(txt(t));
        }
        self
    }

    /// Buttons in a section's head.
    pub fn actions(mut self, a: impl IntoIterator<Item = N>) -> Self {
        if let Kind::Section(s) = &mut self.0.kind {
            s.actions = nodes(a);
        }
        self
    }

    pub fn footer(mut self, a: impl IntoIterator<Item = N>) -> Self {
        if let Kind::Section(s) = &mut self.0.kind {
            s.footer = nodes(a);
        }
        self
    }
}

/// Columns that stack on a phone.
pub fn columns(children: impl IntoIterator<Item = N>) -> N {
    N::of(Kind::Columns(doc::Columns {
        ratios: vec![],
        children: nodes(children),
    }))
}

pub fn section(title: impl Into<Txt>, children: impl IntoIterator<Item = N>) -> N {
    N::of(Kind::Section(doc::Section {
        title: Some(txt(title)),
        description: None,
        actions: vec![],
        children: nodes(children),
        footer: vec![],
    }))
}

pub fn card(children: impl IntoIterator<Item = N>) -> N {
    N::of(Kind::Card(doc::Card {
        trailing: None,
        trailing_format: None,
        title: None,
        children: nodes(children),
    }))
}

pub fn divider() -> N {
    N::of(Kind::Divider {})
}

pub fn split(list: N, detail: N) -> N {
    N::of(Kind::Split(doc::Split {
        list: Box::new(list.0),
        detail: Box::new(detail.0),
        fill: false,
        resize: None,
        expand: None,
    }))
}

/// One tab: its id, title and content.
/// A tab: `tab("unpaid", "Unpaid", [..]).badge(summary.field(Summary::unpaid))`.
pub fn tab(id: &str, title: impl Into<Txt>, children: impl IntoIterator<Item = N>) -> TabB {
    TabB(doc::Tab {
        id: id.into(),
        title: txt(title),
        badge: None,
        children: nodes(children),
    })
}

pub struct TabB(pub doc::Tab);

impl TabB {
    /// A count (or any value) shown next to the title.
    pub fn badge<T>(mut self, v: Val<T>) -> Self {
        self.0.badge = Some(IntoVal::<T>::into_value(v));
        self
    }
}

/// Tabs; the client keeps the selected one unless `.bind_param(..)` or `.bind_state(..)` says where it lives.
pub fn tabs(tabs: impl IntoIterator<Item = TabB>) -> TabsB {
    TabsB(doc::Tabs {
        bind: None,
        tabs: tabs.into_iter().map(|t| t.0).collect(),
    })
}

pub struct TabsB(pub doc::Tabs);

impl TabsB {
    /// The selected tab's id is this screen param (so it is in the link, and queries can read it).
    pub fn bind_param<T>(mut self, p: &ParamRef<T>) -> Self {
        self.0.bind = Some(doc::Bind::Param(p.name.into()));
        self
    }

    /// The selected tab's id is this state.
    pub fn bind_state<T>(mut self, s: &StateRef<T>) -> Self {
        self.0.bind = Some(doc::Bind::State(s.name.clone()));
        self
    }
}

impl From<TabsB> for N {
    fn from(t: TabsB) -> N {
        N::of(Kind::Tabs(t.0))
    }
}

/// What a [`segmented`] writes: a state (`&view`) or a param (`range`, `&range`); `Value` is the type its options
/// are of.
pub trait SegmentedBind {
    type Value;
    fn segmented_bind(&self) -> doc::Bind;
}

impl<T> SegmentedBind for &StateRef<T> {
    type Value = T;
    fn segmented_bind(&self) -> doc::Bind {
        doc::Bind::State(self.name.clone())
    }
}

impl<T> SegmentedBind for ParamRef<T> {
    type Value = T;
    fn segmented_bind(&self) -> doc::Bind {
        doc::Bind::Param(self.name.into())
    }
}

impl<T> SegmentedBind for &ParamRef<T> {
    type Value = T;
    fn segmented_bind(&self) -> doc::Bind {
        doc::Bind::Param(self.name.into())
    }
}

/// A switch between a few options, bound to a state or to a param: a view switch,
/// `segmented(&view, [("list", "List"), ("board", "Board")])`, or the range of a report, in the link,
/// `segmented(range, [("7", "7 days"), ("30", "30 days")])`. The options are values of the state's or the param's
/// type (of its inner type for an `Option`; an enum's values for an enum); give a param a default
/// ([`S::param_or`]) so the switch shows it on a link without the param.
pub fn segmented<B, V, L>(bind: B, options: impl IntoIterator<Item = (V, L)>) -> N
where
    B: SegmentedBind,
    V: LitFor<B::Value>,
    L: Into<Txt>,
{
    N::of(Kind::Segmented(doc::Segmented {
        bind: bind.segmented_bind(),
        options: options
            .into_iter()
            .map(|(v, l)| doc::Opt {
                value: v.lit_json(),
                label: txt(l),
            })
            .collect(),
    }))
}

pub fn link<P>(
    text: impl Into<Txt>,
    screen: ScreenKey<P>,
    args: impl FnOnce(&mut Args<P>) -> &mut Args<P>,
) -> N {
    let mut a = Args::new();
    args(&mut a);
    N::of(Kind::Link(doc::Link {
        text: txt(text),
        target: doc::Target {
            screen: Some(screen.id.into()),
            overlay: None,
            args: a.args,
        },
    }))
}

/// A trail of where a screen sits, separated by `/`, when the sidebar and the screen's title do not say it
/// (a record reached through another record, a step of a drill-down): `breadcrumbs([crumb_to("Orders", ORDERS,
/// |a| a), crumb(order.field(Order::number))])`. Each crumb but the last links to a screen.
pub fn breadcrumbs(items: impl IntoIterator<Item = doc::Crumb>) -> N {
    N::of(Kind::Breadcrumbs(doc::Breadcrumbs {
        items: items.into_iter().collect(),
    }))
}

/// A crumb that is only a text: the screen itself, at the end of the trail.
pub fn crumb(text: impl Into<Txt>) -> doc::Crumb {
    doc::Crumb {
        text: txt(text),
        target: None,
    }
}

/// A crumb that links to a screen, with its params like [`link`].
pub fn crumb_to<P>(
    text: impl Into<Txt>,
    screen: ScreenKey<P>,
    args: impl FnOnce(&mut Args<P>) -> &mut Args<P>,
) -> doc::Crumb {
    let mut a = Args::new();
    args(&mut a);
    doc::Crumb {
        text: txt(text),
        target: Some(doc::Target {
            screen: Some(screen.id.into()),
            overlay: None,
            args: a.args,
        }),
    }
}

/// A table over a query's rows; columns and row values are handles of the row message.
pub struct TableB<R> {
    t: doc::Table,
    _r: PhantomData<fn() -> R>,
}

pub fn table<Resp, R>(q: &Q<Resp, R>) -> TableB<R> {
    TableB {
        t: doc::Table {
            checks: None,
            count: None,
            count_label: None,
            compact: None,
            query: q.name.clone(),
            columns: vec![],
            open: None,
            row_actions: vec![],
            toolbar: vec![],
            select: None,
            empty: None,
            row_tone: vec![],
        },
        _r: PhantomData,
    }
}

impl<R> TableB<R> {
    fn column<T>(mut self, f: Field<R, T>, title: impl Into<Txt>, format: Option<Format>) -> Self {
        self.t.columns.push(doc::Column {
            subtitle: None,
            avatar: None,
            field: f.name.into(),
            title: txt(title),
            format,
            align: None,
            sort: None,
        });
        self
    }

    pub fn col<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, None)
    }

    pub fn mono<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::Mono {}))
    }

    /// A file column (a `File` field): its icon, name and size; a click opens or downloads it.
    pub fn file<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::File {}))
    }

    pub fn number<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        let mut s = self.column(f, title, Some(Format::Number { decimals: None }));
        s.t.columns.last_mut().unwrap().align = Some(doc::Align::End);
        s
    }

    pub fn money<T>(
        self,
        f: Field<R, T>,
        title: impl Into<Txt>,
        currency: Field<R, String>,
    ) -> Self {
        let mut s = self.column(
            f,
            title,
            Some(Format::Money {
                currency: Some(currency.name.into()),
                code: None,
            }),
        );
        s.t.columns.last_mut().unwrap().align = Some(doc::Align::End);
        s
    }

    pub fn money_in<T>(self, f: Field<R, T>, title: impl Into<Txt>, code: &str) -> Self {
        let mut s = self.column(
            f,
            title,
            Some(Format::Money {
                currency: None,
                code: Some(code.into()),
            }),
        );
        s.t.columns.last_mut().unwrap().align = Some(doc::Align::End);
        s
    }

    pub fn date<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::Date {}))
    }

    pub fn datetime<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::Datetime {}))
    }

    pub fn relative<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::Relative { short: false }))
    }

    pub fn member<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::Member {}))
    }

    pub fn avatar<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::Avatar {}))
    }

    pub fn tags<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::Tags {}))
    }

    pub fn percent<T>(self, f: Field<R, T>, title: impl Into<Txt>) -> Self {
        self.column(f, title, Some(Format::Percent { decimals: None }))
    }

    /// An enum column drawn as a status with a tone per value.
    pub fn status<E: crate::message::Enum>(
        self,
        f: Field<R, E>,
        title: impl Into<Txt>,
        tones: impl IntoIterator<Item = (E, Tone)>,
    ) -> Self {
        let tones = tones
            .into_iter()
            .map(|(e, t)| (e.as_str().to_string(), t))
            .collect();
        self.column(f, title, Some(Format::Status { tones }))
    }

    /// The action run when a row is opened.
    pub fn open(mut self, a: &ActionRef) -> Self {
        self.t.open = Some(a.0.clone());
        self
    }

    /// A button (or menu) on every row.
    pub fn row_button(mut self, f: impl FnOnce(Row<R>) -> N) -> Self {
        self.t.row_actions.push(f(Row::new()).0);
        self
    }

    pub fn toolbar(mut self, nodes_: impl IntoIterator<Item = N>) -> Self {
        self.t.toolbar = nodes(nodes_);
        self
    }

    pub fn empty(mut self, t: impl Into<Txt>) -> Self {
        self.t.empty = Some(txt(t));
        self
    }

    /// The selected row's key goes into this state.
    pub fn select<K>(mut self, state: &StateRef<K>, key: Field<R, K>) -> Self {
        self.t.select = Some(doc::Selection {
            state: state.name.clone(),
            key: key.name.into(),
        });
        self
    }

    /// A tone for rows that match.
    pub fn row_tone(mut self, f: impl FnOnce(Row<R>) -> Cond, tone: Tone) -> Self {
        self.t.row_tone.push(doc::ToneWhen {
            when: f(Row::new()).0,
            tone,
        });
        self
    }
}

impl<R> From<TableB<R>> for N {
    fn from(t: TableB<R>) -> N {
        N::of(Kind::Table(t.t))
    }
}

/// A list over a query's rows: a title per row, optionally a subtitle, meta, avatar, status.
