/// Label/value pairs of one record.
pub fn fields(items: impl IntoIterator<Item = doc::FieldItem>) -> N {
    N::of(Kind::Fields(doc::Fields {
        title: None,
        items: items.into_iter().collect(),
    }))
}

/// One label/value pair (`item("Total", order.field(Order::total)).money_in("USD")`).
pub fn item<T>(label: impl Into<Txt>, v: Val<T>) -> doc::FieldItem {
    doc::FieldItem {
        open: None,
        avatar: None,
        label: txt(label),
        value: v.v,
        format: None,
    }
}

/// Formats for a field item, a metric or a text.
pub trait Formatted: Sized {
    fn set_format(&mut self, f: Format);
    fn money_in(mut self, code: &str) -> Self {
        self.set_format(Format::Money {
            currency: None,
            code: Some(code.into()),
        });
        self
    }
    fn number(mut self) -> Self {
        self.set_format(Format::Number { decimals: None });
        self
    }
    fn percent(mut self) -> Self {
        self.set_format(Format::Percent { decimals: None });
        self
    }
    fn date(mut self) -> Self {
        self.set_format(Format::Date {});
        self
    }
    fn datetime(mut self) -> Self {
        self.set_format(Format::Datetime {});
        self
    }
    fn relative(mut self) -> Self {
        self.set_format(Format::Relative { short: false });
        self
    }
    fn member(mut self) -> Self {
        self.set_format(Format::Member {});
        self
    }
    fn status(mut self, tones: impl IntoIterator<Item = (&'static str, Tone)>) -> Self {
        self.set_format(Format::Status {
            tones: tones.into_iter().map(|(k, t)| (k.to_string(), t)).collect(),
        });
        self
    }
}

impl Formatted for doc::FieldItem {
    fn set_format(&mut self, f: Format) {
        self.format = Some(f);
    }
}

impl Formatted for N {
    fn set_format(&mut self, f: Format) {
        match &mut self.0.kind {
            Kind::Metric(m) => m.format = Some(f),
            Kind::Text(t) => t.format = Some(f),
            Kind::Chart(c) => c.format = Some(f),
            Kind::Card(c) => c.trailing_format = Some(f),
            _ => {}
        }
    }
}

pub fn metric<T>(title: impl Into<Txt>, v: Val<T>) -> N {
    N::of(Kind::Metric(doc::Metric {
        caption_tone: None,
        caption_icon: None,
        title: txt(title),
        value: v.v,
        format: None,
        delta: None,
        caption: None,
    }))
}

impl N {
    /// A metric's change next to its value.
    pub fn delta<T>(mut self, v: Val<T>) -> Self {
        if let Kind::Metric(m) = &mut self.0.kind {
            m.delta = Some(v.v);
        }
        self
    }

    pub fn caption(mut self, t: impl Into<Txt>) -> Self {
        match &mut self.0.kind {
            Kind::Metric(m) => m.caption = Some(txt(t)),
            Kind::Meter(m) => m.caption = Some(txt(t)),
            Kind::Progress(m) => m.caption = Some(txt(t)),
            _ => {}
        }
        self
    }

    /// A chart's or a card's title.
    pub fn titled(mut self, t: impl Into<Txt>) -> Self {
        match &mut self.0.kind {
            Kind::Chart(c) => c.title = Some(txt(t)),
            Kind::Card(c) => c.title = Some(txt(t)),
            Kind::Fields(f) => f.title = Some(txt(t)),
            _ => {}
        }
        self
    }
}

/// A chart over a query's rows: the first charts (catalog 1), kept for compatibility. New screens use
/// [`viz`](mod@viz) (`viz::bar::column()`, `viz::line::line()`, …), which has every kind of the charts catalogue.
pub struct ChartB<R> {
    c: doc::Chart,
    _r: PhantomData<fn() -> R>,
}

fn chart<Resp, R, X>(kind: ChartKind, q: &Q<Resp, R>, x: Field<R, X>) -> ChartB<R> {
    ChartB {
        c: doc::Chart {
            kind,
            query: q.name.clone(),
            x: x.name.into(),
            series: vec![],
            title: None,
            format: None,
        },
        _r: PhantomData,
    }
}

pub fn bar_chart<Resp, R, X>(q: &Q<Resp, R>, x: Field<R, X>) -> ChartB<R> {
    chart(ChartKind::Bar, q, x)
}

pub fn line_chart<Resp, R, X>(q: &Q<Resp, R>, x: Field<R, X>) -> ChartB<R> {
    chart(ChartKind::Line, q, x)
}

pub fn area_chart<Resp, R, X>(q: &Q<Resp, R>, x: Field<R, X>) -> ChartB<R> {
    chart(ChartKind::Area, q, x)
}

pub fn pie_chart<Resp, R, X>(q: &Q<Resp, R>, x: Field<R, X>) -> ChartB<R> {
    chart(ChartKind::Pie, q, x)
}

impl<R> ChartB<R> {
    pub fn series<T>(mut self, f: Field<R, T>, label: impl Into<Txt>) -> Self {
        self.c.series.push(doc::Series {
            field: f.name.into(),
            label: txt(label),
        });
        self
    }

    pub fn title(mut self, t: impl Into<Txt>) -> Self {
        self.c.title = Some(txt(t));
        self
    }

    pub fn money_in(mut self, code: &str) -> Self {
        self.c.format = Some(Format::Money {
            currency: None,
            code: Some(code.into()),
        });
        self
    }
}

impl<R> From<ChartB<R>> for N {
    fn from(c: ChartB<R>) -> N {
        N::of(Kind::Chart(c.c))
    }
}

// ---------------------------------------------------------------------------------------------- dashboards

/// A dashboard (catalog revision 2): cards on one shared 12-column grid. The items flow left to right and wrap when
/// a row is full; every row is as tall as its tallest card, and a narrower screen widens the cards (a quarter
/// becomes a half, then everything stacks).
///
/// ```ignore
/// board()
///     .quarter(viz::figure::metric().title("Revenue").value("value", summary.field(Summary::revenue)))
///     .quarter(viz::figure::metric().title("Orders").value("value", summary.field(Summary::orders)))
///     .half(viz::meter::gauge().title("Target").value("value", summary.field(Summary::share)))
///     .full(heading("Sales"))
///     .span(8, viz::line::line().dates(&sales, Day::day).values(&sales, Day::total))
///     .third(viz::part::donut().rows(&channels, (("name", Channel::name), ("value", Channel::total))).to("parts"))
///     .into()
/// ```
///
/// A chart is placed on the board itself (it draws its own card). A board is not put inside another board, and
/// holds at most 60 items. An older client (catalog 1) draws the board's `.fallback(..)`.
#[derive(Clone, Debug, Default)]
pub struct BoardB {
    b: Vec<doc::BoardItem>,
}

/// A dashboard: `board().quarter(a).quarter(b).half(c).span(8, d).third(e)`.
pub fn board() -> BoardB {
    BoardB::default()
}

impl BoardB {
    /// An item `columns` wide, of the grid's 12.
    pub fn span(mut self, columns: u32, n: impl Into<N>) -> Self {
        self.b.push(doc::BoardItem {
            span: columns,
            node: n.into().0,
        });
        self
    }

    /// An item of the full width: a wide chart, a table, a heading between groups.
    pub fn full(self, n: impl Into<N>) -> Self {
        self.span(doc::BOARD_COLUMNS, n)
    }

    /// An item of half the width (6 columns).
    pub fn half(self, n: impl Into<N>) -> Self {
        self.span(6, n)
    }

    /// An item of a third of the width (4 columns).
    pub fn third(self, n: impl Into<N>) -> Self {
        self.span(4, n)
    }

    /// An item of a quarter of the width (3 columns): a row of four metrics.
    pub fn quarter(self, n: impl Into<N>) -> Self {
        self.span(3, n)
    }

    /// What an older client draws instead of the whole board; answers the node.
    pub fn fallback(self, n: impl Into<N>) -> N {
        N::from(self).fallback(n.into())
    }

    /// Shown only while the condition holds; answers the node.
    pub fn visible(self, c: Cond) -> N {
        N::from(self).visible(c)
    }
}

impl From<BoardB> for N {
    fn from(b: BoardB) -> N {
        N::of(Kind::Board(doc::Board { children: b.b }))
    }
}

// ---------------------------------------------------------------------------------------------- charts and figures

/// A chart or a figure of the charts catalogue (catalog revision 2): a kind of a family, its static options and
/// the data bound into them from the screen's queries.
///
/// ```ignore
/// viz::line::line()
///     .title("Revenue")
///     .range("Last 30 days")
///     .option("fmt", "money")
///     .dates(&sales, Day::day)
///     .values(&sales, Day::total)
///     .open(ORDERS, |a| a)
/// ```
///
/// The data methods add a bind each, in order; `.to(..)`, `.as_text()`, `.as_date()` and `.text_keys(..)` change
/// the bind just added. A chart draws its own card: place it on a [`board`], in `columns` or in a `stack`, not next
/// to other children of a `card` or a `section`. An older client (catalog 1) draws the node's `.fallback(..)`.
#[derive(Clone, Debug)]
pub struct VizB {
    v: doc::Viz,
}

/// A chart or figure by the names of its family and kind (`viz("line", "line")`); [`viz`](mod@viz) has a
/// constructor per kind of the catalogue (`viz::line::line()`), which cannot name a kind that does not exist.
pub fn viz(family: &str, kind: &str) -> VizB {
    VizB {
        v: doc::Viz {
            family: family.into(),
            kind: kind.into(),
            title: None,
            range: None,
            options: serde_json::Map::new(),
            bind: vec![],
            height: None,
            select: None,
            open: None,
            time: None,
            connection: None,
            layers: vec![],
        },
    }
}

macro_rules! viz_constructors {
    ($($family:ident { $($kind:ident $($name:literal)?),* $(,)? })*) => {
        /// The charts catalogue: a constructor per kind, by family (`viz::line::line()`, `viz::bar::column()`,
        /// `viz::figure::metric()`). Each answers a [`VizB`].
        pub mod viz {
            $(
                #[doc = concat!("The kinds of the `", stringify!($family), "` family.")]
                pub mod $family {
                    $(
                        #[doc = concat!(
                            "The kind `", celobus_descriptor::viz_kind_name!($kind $($name)?),
                            "` of the family `", stringify!($family), "`."
                        )]
                        pub fn $kind() -> super::super::VizB {
                            super::super::viz(
                                stringify!($family),
                                celobus_descriptor::viz_kind_name!($kind $($name)?),
                            )
                        }
                    )*
                }
            )*
        }
    };
}
celobus_descriptor::viz_catalogue!(viz_constructors);

// ---------------------------------------------------------------------------------------------- time travel

pub use celobus_descriptor::ui::{TimeCompare, TimeControl, TimeGrain};

/// Time travel of a chart or figure (catalog revision 4), for [`VizB::time`]: what the numbers are, the periods
/// (rows of a query: their key and label), and the state or param that holds the shown period.
///
/// ```ignore
/// Time::flow(&quarters, Quarter::key, Quarter::label)
///     .at(quarter)                 // a param or a state: the period's key
///     .track(Quarter::total)       // the headline per period, drawn in the control
///     .partial(Quarter::running)   // the period still running ("to date")
///     .compare(then)               // the second pin: "Compare" in the head
///     .compare_by(TimeCompare::Year) // what Compare offers first
///     .upto(upto)                  // the days a running period has run: the earlier one is cut at the same day
///     .control(TimeControl::Brush)
///     .window(window)              // how many periods the card sums
///     .grain(TimeGrain::Quarter)
/// ```
pub struct Time;

impl Time {
    fn of<Resp, R, V, L>(
        read: doc::TimeRead,
        q: &Q<Resp, R>,
        value: Field<R, V>,
        label: Field<R, L>,
    ) -> TimeB {
        TimeB {
            t: doc::VizTime {
                read,
                control: None,
                periods: doc::TimePeriods {
                    query: q.name.clone(),
                    value: value.name.into(),
                    label: label.name.into(),
                    date: None,
                    track: None,
                    partial: None,
                },
                at: doc::Bind::Param(String::new()),
                window: None,
                then: None,
                compare: None,
                upto: None,
                grain: None,
                key: None,
            },
            at: false,
        }
    }

    /// Sums over a period (revenue in a quarter); the periods are the rows of `q`, `value` their key (written into
    /// the state or param of `.at(..)` and passed to the endpoints) and `label` their name.
    pub fn flow<Resp, R, V, L>(q: &Q<Resp, R>, value: Field<R, V>, label: Field<R, L>) -> TimeB {
        Self::of(doc::TimeRead::Flow, q, value, label)
    }

    /// Levels on a date (stock at the quarter's end): the head says "On …" with the period's `.date(..)`.
    pub fn state<Resp, R, V, L>(q: &Q<Resp, R>, value: Field<R, V>, label: Field<R, L>) -> TimeB {
        Self::of(doc::TimeRead::State, q, value, label)
    }

    /// Dates still to come (deliveries booked): the periods after the running one (`.partial(..)`, which this read
    /// needs) are outlined, past a Today line.
    pub fn scheduled<Resp, R, V, L>(
        q: &Q<Resp, R>,
        value: Field<R, V>,
        label: Field<R, L>,
    ) -> TimeB {
        Self::of(doc::TimeRead::Scheduled, q, value, label)
    }
}

/// A [`Time`] being built: `.at(..)` is required.
#[derive(Clone, Debug)]
pub struct TimeB {
    t: doc::VizTime,
    at: bool,
}

impl TimeB {
    /// The state or param that holds the shown period (a period's key). Empty: the latest period that is not still
    /// to come.
    pub fn at(mut self, target: impl SegmentedBind) -> Self {
        self.t.at = target.segmented_bind();
        self.at = true;
        self
    }

    /// The state or param of the second pin: the head gets "Compare", whose menu offers the same period a year
    /// before, the period before, or one picked by hand; the card's queries are read once more with it in place
    /// of the shown period.
    pub fn compare(mut self, then: impl SegmentedBind) -> Self {
        self.t.then = Some(then.segmented_bind());
        self
    }

    /// What "Compare" offers first: `Year` (the same period a year before; needs [`grain`](Self::grain), and is
    /// the default with one) or `Previous` (the period just before; the default without a grain).
    pub fn compare_by(mut self, by: TimeCompare) -> Self {
        self.t.compare = Some(by);
        self
    }

    /// The state or param (an integer) of the cut of a running period: while the shown period still runs, the
    /// client writes into it the days of that period run so far (from its start, today included: Q4 to Nov 26
    /// is 57) and passes it to both reads, so the endpoint answers the earlier period cut at the same day.
    /// Empty when the shown period is whole. Needs [`partial`](Self::partial) and [`grain`](Self::grain).
    pub fn upto(mut self, upto: impl SegmentedBind) -> Self {
        self.t.upto = Some(upto.segmented_bind());
        self
    }

    /// The state or param (an integer) of how many periods the card sums: the brush's width.
    pub fn window(mut self, window: impl SegmentedBind) -> Self {
        self.t.window = Some(window.segmented_bind());
        self
    }

    /// The control's form (`Strip` when not set).
    pub fn control(mut self, control: TimeControl) -> Self {
        self.t.control = Some(control);
        self
    }

    /// The length of a period: the words of a window, how far "a year before" goes back and the calendar
    /// [`upto`](Self::upto) counts in (without it "Compare" offers the period before).
    pub fn grain(mut self, grain: TimeGrain) -> Self {
        self.t.grain = Some(grain);
        self
    }

    /// A number field of the periods' rows: the card's headline per period, drawn in the control.
    pub fn track<R, T>(mut self, f: Field<R, T>) -> Self {
        self.t.periods.track = Some(f.name.into());
        self
    }

    /// A bool field of the periods' rows: the period still running ("to date").
    pub fn partial<R>(mut self, f: Field<R, bool>) -> Self {
        self.t.periods.partial = Some(f.name.into());
        self
    }

    /// A field of the periods' rows: the date a level is on (`30 Sep 2026`), for [`Time::state`].
    pub fn date<R, T>(mut self, f: Field<R, T>) -> Self {
        self.t.periods.date = Some(f.name.into());
        self
    }

    /// A grid that compares: the column (its index in a row) its change column compares.
    pub fn key(mut self, column: u32) -> Self {
        self.t.key = Some(column);
        self
    }

    fn build(self) -> doc::VizTime {
        assert!(
            self.at,
            "time travel needs the state or param of the shown period: .at(..)"
        );
        self.t
    }
}

// ---------------------------------------------------------------------------------------------- maps

/// A layer of a map (`viz::geo::map()`, catalog revision 4), for [`VizB::layer`]: the rows of a query in lat/lon
/// (or GeoJSON shapes) with their values. Each role has its method; the field types are checked by `celobus
/// plugin check`.
pub struct MapLayer;

impl MapLayer {
    fn over<Resp, R>(kind: doc::MapLayerKind, q: &Q<Resp, R>) -> MapLayerB<R> {
        MapLayerB {
            l: doc::MapLayer {
                kind,
                query: Some(q.name.clone()),
                fields: BTreeMap::new(),
                title: None,
                options: serde_json::Map::new(),
                select: None,
            },
            _r: PhantomData,
        }
    }

    /// Places as dots (`lat`, `lon`; `value`, `name`, `id`, `group`, `stage`, `flag`): sized by the value with
    /// `.option("size", true)`.
    pub fn points<Resp, R>(q: &Q<Resp, R>) -> MapLayerB<R> {
        Self::over(doc::MapLayerKind::Points, q)
    }

    /// The points summed into hexagons (`lat`, `lon`; `value`).
    pub fn hex<Resp, R>(q: &Q<Resp, R>) -> MapLayerB<R> {
        Self::over(doc::MapLayerKind::Hex, q)
    }

    /// Polygons filled by their value, group or order (`shape`: a GeoJSON geometry; `value`, `name`, `id`,
    /// `group`).
    pub fn regions<Resp, R>(q: &Q<Resp, R>) -> MapLayerB<R> {
        Self::over(doc::MapLayerKind::Regions, q)
    }

    /// Marks over the regions: squares or rings at places, their area the value (`lat`, `lon`; `value`, `name`,
    /// `id`).
    pub fn marks<Resp, R>(q: &Q<Resp, R>) -> MapLayerB<R> {
        Self::over(doc::MapLayerKind::Marks, q)
    }

    /// Lines between places, their width the value (`.from(lat, lon)`, `.to(lat, lon)`; `value`, `name`).
    pub fn flows<Resp, R>(q: &Q<Resp, R>) -> MapLayerB<R> {
        Self::over(doc::MapLayerKind::Flows, q)
    }

    /// Rings at distances round each place (`lat`, `lon`; `name`): `.option("distances", json!([1, 2, 3]))`.
    pub fn rings<Resp, R>(q: &Q<Resp, R>) -> MapLayerB<R> {
        Self::over(doc::MapLayerKind::Rings, q)
    }

    /// Places new, still there or gone between two dates (`lat`, `lon`, `state`; `value`, `name`, `id`).
    pub fn change<Resp, R>(q: &Q<Resp, R>) -> MapLayerB<R> {
        Self::over(doc::MapLayerKind::Change, q)
    }

    /// Our share of the points in each hexagon, against the market's (`lat`, `lon`, `ours`).
    pub fn share<Resp, R>(q: &Q<Resp, R>) -> MapLayerB<R> {
        Self::over(doc::MapLayerKind::Share, q)
    }

    /// An area the member draws: its polygon (GeoJSON text) goes to the state or param of `.select_state(..)` /
    /// `.select_param(..)`, which the screen's queries pass to filter by it.
    pub fn area() -> MapLayerB<()> {
        MapLayerB {
            l: doc::MapLayer {
                kind: doc::MapLayerKind::Area,
                query: None,
                fields: BTreeMap::new(),
                title: None,
                options: serde_json::Map::new(),
                select: None,
            },
            _r: PhantomData,
        }
    }
}

/// A [`MapLayer`] being built over rows of type `R`.
pub struct MapLayerB<R> {
    l: doc::MapLayer,
    _r: PhantomData<fn() -> R>,
}

impl<R> MapLayerB<R> {
    /// The row field of a role of the layer's type (`lat`, `value`, `frame`, …).
    pub fn field<T>(mut self, role: &str, f: Field<R, T>) -> Self {
        self.l.fields.insert(role.into(), f.name.into());
        self
    }

    pub fn lat<T>(self, f: Field<R, T>) -> Self {
        self.field("lat", f)
    }

    pub fn lon<T>(self, f: Field<R, T>) -> Self {
        self.field("lon", f)
    }

    pub fn value<T>(self, f: Field<R, T>) -> Self {
        self.field("value", f)
    }

    pub fn name<T>(self, f: Field<R, T>) -> Self {
        self.field("name", f)
    }

    /// What a pick writes to the layer's `select` (else its `name`); how a place is paired between two periods.
    pub fn id<T>(self, f: Field<R, T>) -> Self {
        self.field("id", f)
    }

    pub fn group<T>(self, f: Field<R, T>) -> Self {
        self.field("group", f)
    }

    pub fn stage<T>(self, f: Field<R, T>) -> Self {
        self.field("stage", f)
    }

    /// A bool: the place is ringed (a deal at offer too long).
    pub fn flag(self, f: Field<R, bool>) -> Self {
        self.field("flag", f)
    }

    /// Small multiples: rows with the same frame go on one small map, the maps side by side on one scale.
    pub fn frame<T>(self, f: Field<R, T>) -> Self {
        self.field("frame", f)
    }

    /// A GeoJSON geometry (a `Polygon` or `MultiPolygon`): a JSON field, or a string holding its text.
    pub fn shape<T>(self, f: Field<R, T>) -> Self {
        self.field("shape", f)
    }

    /// `new`, `still` or `gone`, for [`MapLayer::change`].
    pub fn state<T>(self, f: Field<R, T>) -> Self {
        self.field("state", f)
    }

    /// True (or 1) for ours, for [`MapLayer::share`].
    pub fn ours<T>(self, f: Field<R, T>) -> Self {
        self.field("ours", f)
    }

    /// Where a flow starts.
    pub fn from<A, B>(self, lat: Field<R, A>, lon: Field<R, B>) -> Self {
        self.field("from_lat", lat).field("from_lon", lon)
    }

    /// Where a flow ends.
    pub fn to<A, B>(self, lat: Field<R, A>, lon: Field<R, B>) -> Self {
        self.field("to_lat", lat).field("to_lon", lon)
    }

    /// The layer's name in the key.
    pub fn title(mut self, t: impl Into<Txt>) -> Self {
        self.l.title = Some(txt(t));
        self
    }

    /// A static option of the layer: `.option("size", true)`, `.option("fmt", "money")`.
    pub fn option(mut self, name: &str, value: impl Into<Json>) -> Self {
        self.l.options.insert(name.into(), value.into());
        self
    }

    /// The state that receives what the member picks (a place's `id`, else its `name`; the drawn polygon of an
    /// area), or null when nothing is picked.
    pub fn select_state<T>(mut self, state: &StateRef<T>) -> Self {
        self.l.select = Some(doc::Bind::State(state.name.clone()));
        self
    }

    /// The same, into a param of the screen (it is in the URL).
    pub fn select_param<T>(mut self, param: ParamRef<T>) -> Self {
        self.l.select = Some(doc::Bind::Param(param.name.into()));
        self
    }
}

/// What a `viz` option may be bound to with [`VizB::value`]: a [`Val`] of any type (`q.field(Summary::revenue)`),
/// a state, a param or a literal.
pub trait VizValue {
    fn viz_value(self) -> Value;
}

impl<T> VizValue for Val<T> {
    fn viz_value(self) -> Value {
        self.v
    }
}

impl<T> VizValue for &Val<T> {
    fn viz_value(self) -> Value {
        self.v.clone()
    }
}

impl<T> VizValue for &StateRef<T> {
    fn viz_value(self) -> Value {
        Value::State(self.name.clone())
    }
}

impl<T> VizValue for ParamRef<T> {
    fn viz_value(self) -> Value {
        Value::Param(self.name.into())
    }
}

macro_rules! viz_lit {
    ($($t:ty),* $(,)?) => {$(
        impl VizValue for $t {
            fn viz_value(self) -> Value { Value::Lit(serde_json::json!(self)) }
        }
    )*};
}
viz_lit!(&str, String, bool, i32, i64, u32, u64, f64, Json);

/// The fields of a `series` bind with their labels: a tuple of `(field, label)` pairs, whose fields may be of
/// different types (`((Day::online, "Online"), (Day::orders, "Orders"))`), or an array or a `Vec` of pairs of one
/// type.
pub trait VizSeries<R> {
    fn series(self) -> Vec<doc::Series>;
}

/// The keys of a `rows` bind with the row fields they take: a tuple of `(key, field)` pairs, whose fields may be of
/// different types (`(("name", Product::title), ("value", Product::revenue))`), or an array or a `Vec` of pairs of
/// one type.
pub trait VizRows<R> {
    fn map(self) -> BTreeMap<String, String>;
}

fn serie<R, T>(f: Field<R, T>, label: impl Into<Txt>) -> doc::Series {
    doc::Series {
        field: f.name.into(),
        label: txt(label),
    }
}

impl<R, T, L: Into<Txt>, const N: usize> VizSeries<R> for [(Field<R, T>, L); N] {
    fn series(self) -> Vec<doc::Series> {
        self.into_iter().map(|(f, l)| serie(f, l)).collect()
    }
}

impl<R, T, L: Into<Txt>> VizSeries<R> for Vec<(Field<R, T>, L)> {
    fn series(self) -> Vec<doc::Series> {
        self.into_iter().map(|(f, l)| serie(f, l)).collect()
    }
}

impl<R, T, K: AsRef<str>, const N: usize> VizRows<R> for [(K, Field<R, T>); N] {
    fn map(self) -> BTreeMap<String, String> {
        self.into_iter()
            .map(|(k, f)| (k.as_ref().to_string(), f.name.to_string()))
            .collect()
    }
}

impl<R, T, K: AsRef<str>> VizRows<R> for Vec<(K, Field<R, T>)> {
    fn map(self) -> BTreeMap<String, String> {
        self.into_iter()
            .map(|(k, f)| (k.as_ref().to_string(), f.name.to_string()))
            .collect()
    }
}

macro_rules! viz_tuples {
    ($(($($T:ident $L:ident),+))*) => {$(
        #[allow(non_snake_case)]
        impl<R, $($T, $L: Into<Txt>),+> VizSeries<R> for ($((Field<R, $T>, $L),)+) {
            fn series(self) -> Vec<doc::Series> {
                let ($($T,)+) = self;
                vec![$(serie($T.0, $T.1)),+]
            }
        }

        #[allow(non_snake_case)]
        impl<R, $($T, $L: AsRef<str>),+> VizRows<R> for ($(($L, Field<R, $T>),)+) {
            fn map(self) -> BTreeMap<String, String> {
                let ($($T,)+) = self;
                BTreeMap::from([$(($T.0.as_ref().to_string(), $T.1.name.to_string())),+])
            }
        }
    )*};
}
viz_tuples! {
    (A LA)
    (A LA, B LB)
    (A LA, B LB, C LC)
    (A LA, B LB, C LC, D LD)
    (A LA, B LB, C LC, D LD, E LE)
    (A LA, B LB, C LC, D LD, E LE, F LF)
    (A LA, B LB, C LC, D LD, E LE, F LF, G LG)
    (A LA, B LB, C LC, D LD, E LE, F LF, G LG, H LH)
    (A LA, B LB, C LC, D LD, E LE, F LF, G LG, H LH, I LI)
    (A LA, B LB, C LC, D LD, E LE, F LF, G LG, H LH, I LI, J LJ)
    (A LA, B LB, C LC, D LD, E LE, F LF, G LG, H LH, I LI, J LJ, K LK)
    (A LA, B LB, C LC, D LD, E LE, F LF, G LG, H LH, I LI, J LJ, K LK, M LM)
}

impl VizB {
    pub fn title(mut self, t: impl Into<Txt>) -> Self {
        self.v.title = Some(txt(t));
        self
    }

    /// The muted text at the right of the head (`Last 30 days`).
    pub fn range(mut self, t: impl Into<Txt>) -> Self {
        self.v.range = Some(txt(t));
        self
    }

    /// The height in px (16 to 1200); the kind's own height when not set.
    pub fn height(mut self, px: u32) -> Self {
        self.v.height = Some(px);
        self
    }

    /// A static option of the kind: `.option("fmt", "money")`, `.option("target", 120)`,
    /// `.option("bands", json!([50, 80]))` (`json!` is re-exported by this module).
    pub fn option(mut self, name: &str, value: impl Into<Json>) -> Self {
        self.v.options.insert(name.into(), value.into());
        self
    }

    /// Several static options at once: `.options(json!({"fmt": "money", "curve": "smooth"}))`.
    ///
    /// # Panics
    ///
    /// When `options` is not a JSON object.
    pub fn options(mut self, options: Json) -> Self {
        match options {
            Json::Object(m) => self.v.options.extend(m),
            other => panic!("the options of a viz are a JSON object, not {other}"),
        }
        self
    }

    /// A bind written by hand (the typed methods below cover the sources).
    pub fn bind(mut self, to: &str, from: doc::VizSource) -> Self {
        self.v.bind.push(doc::VizBind {
            to: to.into(),
            from,
        });
        self
    }

    /// A row field of every row, as an array in the option `to`. Numbers and numeric strings become numbers;
    /// `.as_text()` keeps strings, `.as_date()` makes short date labels.
    pub fn column<Resp, R, T>(self, to: &str, q: &Q<Resp, R>, f: Field<R, T>) -> Self {
        self.bind(
            to,
            doc::VizSource::Column {
                query: q.name.clone(),
                field: f.name.into(),
                cast: None,
            },
        )
    }

    /// The `labels` (the x positions or the row names) from a row field, kept as text.
    pub fn labels<Resp, R, T>(self, q: &Q<Resp, R>, f: Field<R, T>) -> Self {
        self.column("labels", q, f).as_text()
    }

    /// The `labels` from a date or timestamp field, as short dates (`Nov 4`).
    pub fn dates<Resp, R, T>(self, q: &Q<Resp, R>, f: Field<R, T>) -> Self {
        self.column("labels", q, f).as_date()
    }

    /// The `values` (one series) from a row field.
    pub fn values<Resp, R, T>(self, q: &Q<Resp, R>, f: Field<R, T>) -> Self {
        self.column("values", q, f)
    }

    /// One more series of the option `series`: the row field with its name in the legend. Calls one after another
    /// over the same query (also after `.series(..)`) make one bind.
    pub fn serie<Resp, R, T>(
        mut self,
        q: &Q<Resp, R>,
        f: Field<R, T>,
        label: impl Into<Txt>,
    ) -> Self {
        let s = serie(f, label);
        match self.v.bind.last_mut() {
            Some(doc::VizBind {
                to,
                from: doc::VizSource::Series { query, fields },
            }) if to == "series" && *query == q.name => {
                fields.push(s);
                self
            }
            _ => self.bind(
                "series",
                doc::VizSource::Series {
                    query: q.name.clone(),
                    fields: vec![s],
                },
            ),
        }
    }

    /// The option `series`, one series per row field: `.series(&q, ((Day::online, "Online"), (Day::retail,
    /// "Retail")))`.
    pub fn series<Resp, R>(self, q: &Q<Resp, R>, fields: impl VizSeries<R>) -> Self {
        self.bind(
            "series",
            doc::VizSource::Series {
                query: q.name.clone(),
                fields: fields.series(),
            },
        )
    }

    /// Long rows to wide: `labels` gets the distinct values of `x` in row order, the option `series` one series per
    /// distinct value of `series`, with `value` in its cells (`.as_date()` makes the labels short dates).
    pub fn pivot<Resp, R, X, S, V>(
        self,
        q: &Q<Resp, R>,
        x: Field<R, X>,
        series: Field<R, S>,
        value: Field<R, V>,
    ) -> Self {
        self.bind(
            "series",
            doc::VizSource::Pivot {
                query: q.name.clone(),
                x: x.name.into(),
                series: series.name.into(),
                value: value.name.into(),
                cast: None,
            },
        )
    }

    /// The option `rows`: an object per row with the keys given, each from a row field:
    /// `.rows(&top, (("name", Product::title), ("value", Product::revenue)))`. Numeric strings become numbers except
    /// under the keys named by `.text_keys(..)`.
    pub fn rows<Resp, R>(self, q: &Q<Resp, R>, map: impl VizRows<R>) -> Self {
        self.bind(
            "rows",
            doc::VizSource::Rows {
                query: q.name.clone(),
                map: map.map(),
                text: vec![],
            },
        )
    }

    /// The keys of the `rows` bind just added that stay text (a product named `2024` is not a number).
    pub fn text_keys<K: AsRef<str>>(mut self, keys: impl IntoIterator<Item = K>) -> Self {
        if let Some(doc::VizBind {
            from: doc::VizSource::Rows { text, .. },
            ..
        }) = self.v.bind.last_mut()
        {
            text.extend(keys.into_iter().map(|k| k.as_ref().to_string()));
        }
        self
    }

    /// One value in the option `to` (a name or a dotted path: `center.value`): `.value("value",
    /// summary.field(Summary::revenue))`, a state, a param or a literal.
    pub fn value(self, to: &str, v: impl VizValue) -> Self {
        self.bind(to, doc::VizSource::Value(v.viz_value()))
    }

    /// Another option for the bind just added: `.rows(&q, ..).to("parts")`, `.series(&q, ..).to("groups")`.
    pub fn to(mut self, to: &str) -> Self {
        if let Some(b) = self.v.bind.last_mut() {
            b.to = to.into();
        }
        self
    }

    fn cast(mut self, cast: doc::VizAs) -> Self {
        if let Some(
            doc::VizSource::Column { cast: c, .. } | doc::VizSource::Pivot { cast: c, .. },
        ) = self.v.bind.last_mut().map(|b| &mut b.from)
        {
            *c = Some(cast);
        }
        self
    }

    /// The `column` just added keeps its cells as text (the labels of a `pivot` too).
    pub fn as_text(self) -> Self {
        self.cast(doc::VizAs::Text)
    }

    /// The `column` just added (or the labels of the `pivot`) holds ISO dates or datetimes: they become short
    /// labels (`Nov 4`, with the year when the rows span more than one).
    pub fn as_date(self) -> Self {
        self.cast(doc::VizAs::Date)
    }

    /// The state that receives what the member picks in the chart (a bar, a slice, a row): the picked value, or
    /// null when nothing is picked. Queries and conditions of the screen read it like any state.
    pub fn select_state<T>(mut self, state: &StateRef<T>) -> Self {
        self.v.select = Some(doc::Bind::State(state.name.clone()));
        self
    }

    /// The same, into a param of the screen (it is in the URL).
    pub fn select_param<T>(mut self, param: &ParamRef<T>) -> Self {
        self.v.select = Some(doc::Bind::Param(param.name.into()));
        self
    }

    /// The screen the card's link leads to, with its params like a [`link`] (a literal, a param, a state):
    /// `.open(ORDERS, |a| a.arg(OrdersParams::status, OrderStatus::Paid))`, `.open(REPORT, |a| a)`.
    pub fn open<P>(
        mut self,
        screen: ScreenKey<P>,
        args: impl FnOnce(&mut Args<P>) -> &mut Args<P>,
    ) -> Self {
        let mut a = Args::new();
        args(&mut a);
        self.v.open = Some(doc::Target {
            screen: Some(screen.id.into()),
            overlay: None,
            args: a.args,
        });
        self
    }

    /// Time travel (catalog revision 4): the period the card shows, moved by a control at its foot, and a second
    /// period to compare with: `.time(Time::flow(&quarters, Quarter::key, Quarter::label).at(quarter))`. The
    /// card's queries pass the shown period (`.arg(Request::quarter, quarter)`); the client reads them again when
    /// it moves.
    pub fn time(mut self, t: TimeB) -> Self {
        self.v.time = Some(t.build());
        self
    }

    /// A map's basemap (`viz::geo::map()`): the `maps` connection it comes from, a connection of this plugin by
    /// its name (`"maps"`) or `<dependency>.<name>`.
    pub fn connection(mut self, name: impl Into<String>) -> Self {
        self.v.connection = Some(name.into());
        self
    }

    /// A layer of a map, drawn over the ones before it (at most 8): `.layer(MapLayer::points(&deals).lat(Deal::lat)
    /// .lon(Deal::lon))`.
    pub fn layer<R>(mut self, l: MapLayerB<R>) -> Self {
        self.v.layers.push(l.l);
        self
    }

    /// What an older client draws instead (a table, a metric, a text); answers the node.
    pub fn fallback(self, n: impl Into<N>) -> N {
        N::from(self).fallback(n.into())
    }

    /// Shown only while the condition holds; answers the node.
    pub fn visible(self, c: Cond) -> N {
        N::from(self).visible(c)
    }
}

impl From<VizB> for N {
    fn from(v: VizB) -> N {
        N::of(Kind::Viz(v.v))
    }
}

