/// The inputs of a form over `Req`.
pub struct FormB<Req> {
    sections: Vec<doc::FormSection>,
    cancel: Option<Text>,
    summary: Option<doc::FormSummary>,
    note: Option<Text>,
    alternate: Option<(Text, Chain)>,
    notes: Vec<doc::FormNote>,
    phone_submit: Option<Text>,
    _r: PhantomData<fn() -> Req>,
}

impl<Req> FormB<Req> {
    /// The form of a plugin's settings (`Settings::form`): its inputs and sections only.
    pub(crate) fn settings() -> Self {
        Self {
            sections: vec![doc::FormSection {
                title: None,
                inputs: vec![],
            }],
            cancel: None,
            summary: None,
            note: None,
            alternate: None,
            notes: vec![],
            phone_submit: None,
            _r: PhantomData,
        }
    }

    /// Its sections, an empty untitled first one left out.
    pub(crate) fn into_sections(self) -> Vec<doc::FormSection> {
        self.sections
            .into_iter()
            .filter(|s| s.title.is_some() || !s.inputs.is_empty())
            .collect()
    }

    fn add(&mut self, i: doc::Input) -> &mut doc::Input {
        let s = self.sections.last_mut().unwrap();
        s.inputs.push(i);
        s.inputs.last_mut().unwrap()
    }

    fn input<T>(
        &mut self,
        f: Field<Req, T>,
        control: Control,
        label: impl Into<Txt>,
    ) -> InputRef<'_> {
        InputRef(self.add(doc::Input {
            icon: None,
            width: None,
            stepper: false,
            aside: None,
            add_label: None,
            name: f.name.into(),
            control,
            label: txt(label),
            help: None,
            placeholder: None,
            required: false,
            initial: None,
            options: vec![],
            options_from: None,
            fields: vec![],
            min_items: None,
            max_items: None,
            pick: None,
            max_size: None,
            accept: vec![],
            multiple: false,
        }))
    }

    /// Starts a titled section.
    pub fn section(&mut self, title: impl Into<Txt>) -> &mut Self {
        self.sections.push(doc::FormSection {
            title: Some(txt(title)),
            inputs: vec![],
        });
        self
    }

    pub fn cancel(&mut self, label: impl Into<Txt>) -> &mut Self {
        self.cancel = Some(txt(label));
        self
    }

    /// The submit button's label on a phone, where the form is a sheet (absent: the submit label).
    pub fn phone_submit(&mut self, label: impl Into<Txt>) -> &mut Self {
        self.phone_submit = Some(txt(label));
        self
    }

    pub fn text<T>(&mut self, f: Field<Req, T>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Text, label)
    }

    pub fn textarea<T>(&mut self, f: Field<Req, T>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Textarea, label)
    }

    pub fn number<T>(&mut self, f: Field<Req, T>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Number, label)
    }

    pub fn money<T>(&mut self, f: Field<Req, T>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Money, label)
    }

    pub fn date<T>(&mut self, f: Field<Req, T>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Date, label)
    }

    pub fn checkbox(&mut self, f: Field<Req, bool>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Checkbox, label)
    }

    pub fn switch(&mut self, f: Field<Req, bool>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Switch, label)
    }

    pub fn member<T>(&mut self, f: Field<Req, T>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Member, label)
    }

    /// A write-only text drawn as a password field: a settings `Secret`, or a string an endpoint takes (a value already
    /// saved is never shown).
    pub fn secret<T>(&mut self, f: Field<Req, T>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Secret, label)
    }

    /// A select that takes several of an enum's values (a list of them).
    pub fn multi_select<T: SelectOptions>(
        &mut self,
        f: Field<Req, Vec<T>>,
        label: impl Into<Txt>,
    ) -> InputRef<'_> {
        let r = self.input(f, Control::MultiSelect, label);
        r.0.options = T::options();
        r
    }

    /// A drop zone and a picker for a `File` or `Vec<File>` field, within its `max_size` and `accept`: files upload as
    /// they are picked and their ids go with the form.
    pub fn upload<T>(&mut self, f: Field<Req, T>, label: impl Into<Txt>) -> InputRef<'_> {
        self.input(f, Control::Upload, label)
    }

    /// A select over an enum's values.
    pub fn select<T: SelectOptions>(
        &mut self,
        f: Field<Req, T>,
        label: impl Into<Txt>,
    ) -> InputRef<'_> {
        let r = self.input(f, Control::Select, label);
        r.0.options = T::options();
        r
    }

    /// Radio cards over an enum's values.
    pub fn radio<T: SelectOptions>(
        &mut self,
        f: Field<Req, T>,
        label: impl Into<Txt>,
    ) -> InputRef<'_> {
        let r = self.input(f, Control::RadioCards, label);
        r.0.options = T::options();
        r
    }

    /// A select whose options come from a query's rows.
    pub fn select_from<T, Resp, R, V, L>(
        &mut self,
        f: Field<Req, T>,
        label: impl Into<Txt>,
        q: &Q<Resp, R>,
        value: Field<R, V>,
        shown: Field<R, L>,
    ) -> InputRef<'_> {
        let r = self.input(f, Control::Select, label);
        r.0.options_from = Some(doc::OptionsFrom {
            query: q.name.clone(),
            value: value.name.into(),
            label: shown.name.into(),
        });
        r
    }
}

