/// The plugin's UI: `Ui::new().nav(..).screen(..).command(..)`.
#[derive(Default)]
pub struct Ui {
    doc: doc::Ui,
}

/// A sidebar group.
pub struct Nav(doc::NavGroup, Vec<doc::Query>);

impl Nav {
    pub fn group(title: impl Into<Txt>) -> Self {
        Nav(
            doc::NavGroup {
                title: txt(title),
                icon: None,
                entries: vec![],
            },
            vec![],
        )
    }

    pub fn icon(mut self, icon: &str) -> Self {
        self.0.icon = Some(icon.into());
        self
    }

    pub fn entry(mut self, e: Entry) -> Self {
        self.0.entries.push(e.0);
        self.1.extend(e.1);
        self
    }
}

/// A sidebar entry: a screen with its params, an optional badge.
pub struct Entry(doc::NavEntry, Vec<doc::Query>);

impl Entry {
    pub fn to<P>(
        screen: ScreenKey<P>,
        title: impl Into<Txt>,
        args: impl FnOnce(&mut Args<P>) -> &mut Args<P>,
    ) -> Self {
        let mut a = Args::new();
        args(&mut a);
        Entry(
            doc::NavEntry {
                badge_style: Default::default(),
                title: txt(title),
                icon: None,
                screen: Some(screen.id.into()),
                args: a.args,
                badge: None,
                children: vec![],
                rows: None,
            },
            vec![],
        )
    }

    /// Entries from a query's rows (channels, direct messages): `Entry::rows("Channels", query.rows(..),
    /// Channel::name, CHANNEL, |p, r| p.arg(Params::c, r.get(Channel::id)))`, at most five shown with "Show all".
    pub fn rows<Req, Resp, R, L, P>(
        title: impl Into<Txt>,
        q: QueryDef<Req, Resp, R>,
        label: Field<R, L>,
        screen: ScreenKey<P>,
        args: impl FnOnce(&mut Args<P>, Row<R>) -> &mut Args<P>,
    ) -> Self {
        let mut a = Args::new();
        args(&mut a, Row { _r: PhantomData });
        let mut q = q.q;
        q.name = format!("rows_{}", label.name);
        for f in &mut q.follow {
            f.min_interval_ms.get_or_insert(2000);
        }
        Entry(
            doc::NavEntry {
                badge_style: Default::default(),
                title: txt(title),
                icon: None,
                screen: None,
                args: vec![],
                badge: None,
                children: vec![],
                rows: Some(doc::NavRows {
                    query: q.name.clone(),
                    label: label.name.into(),
                    badge: None,
                    mentions: None,
                    icon: None,
                    screen: screen.id.into(),
                    args: a.args,
                    limit: 5,
                    add: None,
                }),
            },
            vec![q],
        )
    }

    /// Rows: a row field with each row's icon name (`hash`, an agent's `bot`).
    pub fn row_icon<R, T>(mut self, f: Field<R, T>) -> Self {
        if let Some(r) = &mut self.0.rows {
            r.icon = Some(f.name.into());
        }
        self
    }

    /// Rows: the unread count of each row (its label turns bold) and the viewer's mentions (an amber pill).
    pub fn unread<R, T, M>(mut self, unread: Field<R, T>, mentions: Field<R, M>) -> Self {
        if let Some(r) = &mut self.0.rows {
            r.badge = Some(unread.name.into());
            r.mentions = Some(mentions.name.into());
        }
        self
    }

    /// Rows: how many show before "Show all" (1 to 20).
    pub fn limit(mut self, n: u32) -> Self {
        if let Some(r) = &mut self.0.rows {
            r.limit = n;
        }
        self
    }

    /// Rows: an add row under them (`New channel`) that opens a document-level overlay.
    pub fn add<P>(mut self, title: impl Into<Txt>, overlay: OverlayKey<P>) -> Self {
        if let Some(r) = &mut self.0.rows {
            r.add = Some(doc::NavAdd {
                title: txt(title),
                overlay: overlay.id.into(),
            });
        }
        self
    }

    pub fn icon(mut self, icon: &str) -> Self {
        self.0.icon = Some(icon.into());
        self
    }

    /// A count from a document-level query, live through the topics it follows.
    pub fn badge<Req, Resp, Row, T>(
        mut self,
        q: QueryDef<Req, Resp, Row>,
        count: Field<Resp, T>,
    ) -> Self {
        let mut q = q.q;
        q.name = format!("badge_{}", count.name);
        for f in &mut q.follow {
            f.min_interval_ms.get_or_insert(2000);
        }
        self.0.badge = Some(Value::Data {
            query: q.name.clone(),
            field: count.name.into(),
        });
        self.1.push(q);
        self
    }
}

/// A command-palette entry.
pub struct Command(doc::Command);

impl Command {
    pub fn navigate<P>(id: &str, title: impl Into<Txt>, screen: ScreenKey<P>) -> Self {
        Command(doc::Command {
            id: id.into(),
            title: txt(title),
            icon: None,
            target: doc::Target {
                screen: Some(screen.id.into()),
                overlay: None,
                args: vec![],
            },
        })
    }

    /// Navigates to a screen with params, like a link: a report at its seven days,
    /// `Command::navigate_with("week", "Sales: last 7 days", REPORT, |a| a.arg(ReportParams::range, "7"))`.
    /// A command runs from anywhere, so its args are literals.
    pub fn navigate_with<P>(
        id: &str,
        title: impl Into<Txt>,
        screen: ScreenKey<P>,
        args: impl FnOnce(&mut Args<P>) -> &mut Args<P>,
    ) -> Self {
        let mut a = Args::new();
        args(&mut a);
        let mut c = Self::navigate(id, title, screen);
        c.0.target.args = a.args;
        c
    }

    /// Opens a document-level overlay (`Ui::overlay`).
    pub fn open<P>(id: &str, title: impl Into<Txt>, overlay: OverlayKey<P>) -> Self {
        Command(doc::Command {
            id: id.into(),
            title: txt(title),
            icon: None,
            target: doc::Target {
                screen: None,
                overlay: Some(overlay.id.into()),
                args: vec![],
            },
        })
    }

    /// Opens a document-level overlay with params (literals): `Command::open_with("new_b2b", "New trade order",
    /// NEW_ORDER, |a| a.arg(NewOrderParams::segment, "trade"))`.
    pub fn open_with<P>(
        id: &str,
        title: impl Into<Txt>,
        overlay: OverlayKey<P>,
        args: impl FnOnce(&mut Args<P>) -> &mut Args<P>,
    ) -> Self {
        let mut a = Args::new();
        args(&mut a);
        let mut c = Self::open(id, title, overlay);
        c.0.target.args = a.args;
        c
    }

    pub fn icon(mut self, icon: &str) -> Self {
        self.0.icon = Some(icon.into());
        self
    }
}

/// The builder a home widget's closure gets: its queries are document-level.
pub struct W<'a> {
    ui: &'a mut Ui,
    prefix: String,
}

impl W<'_> {
    pub fn query<Req, Resp, Row>(
        &mut self,
        name: &str,
        def: QueryDef<Req, Resp, Row>,
    ) -> Q<Resp, Row> {
        let mut q = def.q;
        q.name = format!("{}_{name}", self.prefix);
        for f in &mut q.follow {
            f.min_interval_ms.get_or_insert(2000);
        }
        let name = q.name.clone();
        self.ui.doc.queries.push(q);
        Q {
            name,
            _p: PhantomData,
        }
    }
}

impl Ui {
    pub fn new() -> Self {
        Self::default()
    }

    /// A sidebar group; its entries' badge queries become document-level queries.
    pub fn nav(mut self, n: Nav) -> Self {
        for q in n.1 {
            if !self.doc.queries.iter().any(|x| x.name == q.name) {
                self.doc.queries.push(q);
            }
        }
        self.doc.nav.push(n.0);
        self
    }

    pub fn screen(mut self, s: Screen) -> Self {
        self.doc.screens.push(s.0);
        self
    }

    /// The screen the plugin opens on; it takes no required param (`E_UI_LANDING`). Without it, the client opens
    /// the screen of the navigation's first entry that has one.
    pub fn landing<P>(mut self, screen: ScreenKey<P>) -> Self {
        self.doc.landing = Some(screen.id.into());
        self
    }

    /// An overlay opened from anywhere (a command, a nav "add" row).
    pub fn overlay(mut self, o: Overlay) -> Self {
        self.doc.overlays.push(o.0);
        self
    }

    pub fn command(mut self, c: Command) -> Self {
        self.doc.commands.push(c.0);
        self
    }

    /// A workspace home widget; its closure declares queries and returns the node.
    pub fn home(mut self, id: &str, title: impl Into<Txt>, f: impl FnOnce(&mut W) -> N) -> Self {
        let node = {
            let mut w = W {
                ui: &mut self,
                prefix: format!("home_{id}"),
            };
            f(&mut w).0
        };
        self.doc.home.push(doc::Widget {
            id: id.into(),
            title: txt(title),
            node,
            open: None,
        });
        self
    }

    /// A text in another locale (`en` comes from `t(..)`).
    pub fn text(mut self, locale: &str, key: &str, value: &str) -> Self {
        self.doc
            .texts
            .entry(locale.into())
            .or_default()
            .insert(key.into(), value.into());
        self
    }

    /// The document as the descriptor carries it.
    pub(crate) fn finish(mut self) -> doc::Ui {
        let en: BTreeMap<String, String> = TEXTS.lock().unwrap().clone();
        if !en.is_empty() {
            let cat = self.doc.texts.entry("en".into()).or_default();
            for (k, v) in en {
                cat.entry(k).or_insert(v);
            }
        }
        self.doc.catalog = doc::CATALOG;
        self.doc
    }
}

