/// The inputs of one row of a `repeat`.
pub struct RowForm<T> {
    inputs: Vec<doc::Input>,
    _t: PhantomData<fn() -> T>,
}

impl<T> RowForm<T> {
    fn push<V>(
        &mut self,
        f: Field<T, V>,
        control: Control,
        label: impl Into<Txt>,
    ) -> &mut doc::Input {
        self.inputs.push(doc::Input {
            name: f.name.into(),
            control,
            label: txt(label),
            help: None,
            placeholder: None,
            required: false,
            initial: None,
            options: vec![],
            options_from: None,
            fields: vec![],
            min_items: None,
            max_items: None,
            icon: None,
            width: None,
            stepper: false,
            aside: None,
            add_label: None,
            pick: None,
            max_size: None,
            accept: vec![],
            multiple: false,
        });
        self.inputs.last_mut().unwrap()
    }

    /// A select from a query's rows.
    pub fn select_from<V, Resp, R, A, L>(
        &mut self,
        f: Field<T, V>,
        label: impl Into<Txt>,
        q: &Q<Resp, R>,
        value: Field<R, A>,
        shown: Field<R, L>,
    ) -> &mut Self {
        let i = self.push(f, Control::Select, label);
        i.required = true;
        i.options_from = Some(doc::OptionsFrom {
            query: q.name.clone(),
            value: value.name.into(),
            label: shown.name.into(),
        });
        self
    }

    /// A number with − and + buttons, starting at `initial`.
    pub fn stepper<V>(&mut self, f: Field<T, V>, label: impl Into<Txt>, initial: i64) -> &mut Self {
        let i = self.push(f, Control::Number, label);
        i.stepper = true;
        i.required = true;
        i.initial = Some(Value::Lit(Json::from(initial)));
        self
    }
}

impl<Req> FormB<Req> {
    /// Rows of a repeated message field (`Items`: product, quantity per row).
    pub fn repeat<T>(
        &mut self,
        f: Field<Req, Vec<T>>,
        label: impl Into<Txt>,
        row: impl FnOnce(&mut RowForm<T>),
    ) -> InputRef<'_> {
        let mut rf = RowForm::<T> {
            inputs: vec![],
            _t: PhantomData,
        };
        row(&mut rf);
        let r = self.input(f, Control::Repeat, label);
        r.0.fields = rf.inputs;
        r.0.min_items = Some(1);
        r
    }

    /// A total under the inputs.
    pub fn summary<T>(
        &mut self,
        title: impl Into<Txt>,
        caption: Option<Txt>,
        v: Val<T>,
        money_in: &str,
    ) -> &mut Self {
        self.summary = Some(doc::FormSummary {
            title: txt(title),
            caption: caption.map(|c| c.0),
            value: v.v,
            format: Some(Format::Money {
                currency: None,
                code: Some(money_in.into()),
            }),
        });
        self
    }

    /// A second button that sends the values another way (`Save draft`).
    pub fn alternate(
        &mut self,
        label: impl Into<Txt>,
        f: impl FnOnce(&mut Chain) -> &mut Chain,
    ) -> &mut Self {
        let mut c = Chain::new();
        f(&mut c);
        self.alternate = Some((txt(label), c));
        self
    }

    /// A line next to the buttons.
    pub fn note(&mut self, t: impl Into<Txt>) -> &mut Self {
        self.note = Some(txt(t));
        self
    }
}

